def status_schritte_abschliessen(
    menge=1
):
    if (
        isinstance(menge, bool)
        or not isinstance(menge, int)
        or menge <= 0
    ):
        return True

    for _ in range(menge):
        aktive = status_effekte_aktiv()

        for status_id, aktiv_daten in list(
            aktive.items()
        ):
            if aktiv_daten.get(
                "einheit"
            ) != "schritte":
                continue

            definition = STATUS_EFFEKTE.get(
                status_id,
                {}
            )

            if not definition.get(
                "schaden_ausserhalb_kampf",
                False
            ):
                continue

            tick_schaden = definition.get(
                "schaden_pro_tick",
                0
            )

            if not isinstance(
                tick_schaden,
                (int, float)
            ):
                continue

            stapel = max(
                1,
                aktiv_daten.get(
                    "stapel",
                    1
                )
            )

            schaden = int(
                tick_schaden * stapel
            )

            if schaden <= 0:
                continue

            # Sicherheitsregel: außerhalb des Kampfes nie unter 1 LP.
            # Angezeigt wird nur der Schaden, der wirklich entsteht.
            vorher = spieler["lebenspunkte"]
            begrenzt = vorher - schaden < 1

            spieler[
                "lebenspunkte"
            ] = max(
                1,
                vorher - schaden
            )

            erlitten = max(0, vorher - spieler["lebenspunkte"])

            name = definition.get(
                "name",
                status_id
            )

            print()

            if erlitten > 0:
                design_text(
                    (
                        f"{name}: Du erleidest "
                        f"{erlitten} Schaden."
                    ),
                    design="gefahr",
                    art="menue"
                )

            if begrenzt:
                # Ausführlich beim ersten Erreichen der Grenze, danach kurz.
                erstes_mal = aktiv_daten.get("grenze_gemeldet") is not True
                aktiv_daten["grenze_gemeldet"] = True

                if status_id == "gift" and erstes_mal:
                    print(
                        "Das Gift brennt noch in deinen Adern, aber es reicht "
                        "nicht mehr, um dich zu Fall zu bringen. Du brauchst "
                        "Ruhe oder ein Gegengift."
                    )
                elif status_id == "gift":
                    print(
                        "Das Gift wirkt weiter. Du hältst dich gerade noch auf "
                        "den Beinen."
                    )
                elif erstes_mal:
                    print(
                        "Die Wunde blutet noch, aber du hältst dich auf den "
                        "Beinen."
                    )
                else:
                    print("Die Wunde blutet noch. Du hältst dich auf den Beinen.")

        if spieler[
            "lebenspunkte"
        ] <= 0:
            print()

            design_text(
                "Du brichst an deinen Verletzungen zusammen.",
                design="gefahr",
                art="menue"
            )

            spieler[
                "spiel_laeuft"
            ] = False

            return False

        status_dauer_verringern(
            "schritte"
        )

    return True

def status_anzeigen():
    ort_titel(
        "Status"
    )

    aktive = status_effekte_aktiv()

    if not aktive:
        print(
            "Aktuell sind keine Buffs, Debuffs "
            "oder Statuseffekte aktiv."
        )

        warte_auf_taste(
            "Zurück"
        )

        return

    for status_id, aktiv_daten in (
        aktive.items()
    ):
        definition = STATUS_EFFEKTE.get(
            status_id,
            {}
        )

        design_text(
            definition.get(
                "name",
                status_id
            ),
            design=definition.get(
                "design",
                "wissen"
            ),
            art="menue"
        )

        beschreibung = definition.get(
            "beschreibung"
        )

        if beschreibung:
            print(
                beschreibung
            )

        stapel = aktiv_daten.get(
            "stapel",
            1
        )

        if stapel > 1:
            print(
                f"Stapel: {stapel}"
            )

        dauer = aktiv_daten.get(
            "dauer"
        )

        einheit = aktiv_daten.get(
            "einheit"
        )

        if (
            dauer is not None
            and einheit
        ):
            if einheit == "schritte":
                einheit_text = (
                    "Schritt"
                    if dauer == 1
                    else "Schritte"
                )

            elif einheit == "runden":
                einheit_text = (
                    "Runde"
                    if dauer == 1
                    else "Runden"
                )

            elif einheit == "kaempfe":
                einheit_text = (
                    "Kampf"
                    if dauer == 1
                    else "Kämpfe"
                )

            else:
                einheit_text = einheit

            print(
                f"Dauer: "
                f"{dauer} "
                f"{einheit_text}"
            )

        print()

    warte_auf_taste(
        "Zurück"
    )

def kampf_starten(
    lebenspunkte=100,
    heiltraenke=1,
    waffe=None,
    gegner_typ=None,
    kampf_situation=None,
    reise_umgehen=False
):
    status_kampf_vorbereiten()

    ruestung = ausruestung_holen(
        "ruestung"
    )

    if isinstance(
        ruestung,
        dict
    ):
        ruestung_schutz = (
            ruestung.get(
                "schutz",
                0
            )
        )

    else:
        ruestung_schutz = 0

    kampfwerte = {
        "staerke": spieler_pruefwert(
            "staerke"
        ),
        "ausdauer": spieler_pruefwert(
            "ausdauer"
        ),
        "geschick": spieler_pruefwert(
            "geschick"
        ),
        "zaehigkeit": spieler_pruefwert(
            "zaehigkeit"
        ),
        "wahrnehmung": spieler_pruefwert(
            "wahrnehmung"
        ),
        "sensibilitaet": spieler_pruefwert(
            "sensibilitaet"
        ),
        "ruestung_schutz": ruestung_schutz + talent_bonus(spieler, "schutz"),
        "talent_verteidigung_bonus": talent_bonus(
            spieler,
            "verteidigung_chance"
        ),
        "talent_parade_bonus": talent_bonus(spieler, "parade_chance"),
        "talent_flucht_bonus": talent_bonus(spieler, "flucht_bonus"),
        "talent_heiltrank_bonus": talent_bonus(spieler, "heilung_bonus"),
        "talent_gegenschlag": talent_bonus(spieler, "gegenschlag") > 0,
        "talent_unbeugsam": talent_bonus(spieler, "unbeugsam") > 0,
        "talent_pflege_ganzer_kampf": talent_bonus(spieler, "pflege_ganzer_kampf") > 0,
        "talent_standhaft": talent_bonus(spieler, "standhaft") > 0,
        "talent_nachtauge": talent_bonus(spieler, "nachtauge") > 0,
        "talent_griffbereit": talent_bonus(spieler, "griffbereit") > 0,
        "talent_zweiter_atem": talent_bonus(spieler, "zweiter_atem") > 0,
        "talent_wachsam": talent_bonus(spieler, "wachsam") > 0,
        "talent_heilkundig": talent_bonus(spieler, "heilkundig") > 0,
            "fokus_treffer_bonus": talent_bonus(
            spieler,
            "fokus_trefferchance"
        ),
        "schmied_waffenpflege": schmied_waffenpflege_kampfbonus(spieler, waffe),
        "krieger_deckung_gelernt": grundklasse_holen(spieler) == "kaempfer",
        "spaeher_luecke_gelernt": grundklasse_holen(spieler) == "spaeher",
        "gelehrter_muster_gelernt": grundklasse_holen(spieler) == "gelehrter",
        **magier_resonanzwerte(spieler),
        **bestienjaeger_kampfwerte(spieler, gegner_typ, kampf_situation),
        **stahlkrieger_kampfwerte(spieler, waffe),
        **glutkrieger_kampfwerte(spieler)
    }

    kampfwerte["blutungsschutz"] = ausruestung_kennwert("ruestung", "blutungsschutz")
    kampfwerte["dunkel_milder"] = ausruestung_kennwert("zubehoer", "dunkel_milder")
    # Wachsam: Umgehen nur bei gewöhnlichen Reisebegegnungen, nie während einer Klassenprüfung.
    kampfwerte["reise_umgehen"] = reise_umgehen is True and not (
        kampfwerte["bestienjaeger_pruefung"]
        or kampfwerte["stahlkrieger_pruefung"]
        or kampfwerte["glutkrieger_pruefung"]
    )

    bandagen_vor_kampf = item_anzahl("bandage")
    netze_vor_kampf = item_anzahl("wurfnetz")
    salben_vor_kampf = item_anzahl("wundsalbe")
    gegengifte_vor_kampf = item_anzahl("gegengift")

    ergebnis = kampfsystem_kampf_starten(
        bandagen=bandagen_vor_kampf,
        wurfnetze=netze_vor_kampf,
        wundsalben=salben_vor_kampf,
        wundsalbe_heilung=wundsalbe_heilung(),
        gegengifte=gegengifte_vor_kampf,
        lebenspunkte=lebenspunkte,
        heiltraenke=heiltraenke,
        waffe=waffe,
        gegner_typ=gegner_typ,
        kampfwerte=kampfwerte,
        status_effekte=status_effekte_aktiv(),
        status_definitionen=STATUS_EFFEKTE,
        kampf_situation=kampf_situation
    )

    # Umgangen (Wachsam): kein Kampf, also nichts verbraucht, nichts eingetragen.
    if ergebnis.get("umgangen"):
        return ergebnis

    schmied_waffenpflege_beenden(spieler)
    jagdbuch_eintragen(
        ergebnis.get("gegner_typ"),
        verhalten=ergebnis.get("angekuendigt", [])
    )
    if ergebnis.get("gegner_verschont"):
        spieler["wrackpluenderer_verschont"] = True
    if kampfwerte["glutkrieger_portion"]:
        glutkrieger_portion_verbrauchen(spieler, ergebnis)

    bandagen_rest = ergebnis.get("bandagen", bandagen_vor_kampf)
    if (
        isinstance(bandagen_rest, int)
        and not isinstance(bandagen_rest, bool)
        and 0 <= bandagen_rest <= bandagen_vor_kampf
    ):
        verbraucht = bandagen_vor_kampf - bandagen_rest
        if verbraucht > 0:
            item_entfernen("bandage", verbraucht)

    for item_id, vorher, schluessel in (
        ("wurfnetz", netze_vor_kampf, "wurfnetze"),
        ("wundsalbe", salben_vor_kampf, "wundsalben"),
        ("gegengift", gegengifte_vor_kampf, "gegengifte")
    ):
        rest = ergebnis.get(schluessel, vorher)
        if (
            isinstance(rest, int)
            and not isinstance(rest, bool)
            and 0 <= rest < vorher
        ):
            item_entfernen(item_id, vorher - rest)

    aktualisierte_status = ergebnis.get(
        "status_effekte"
    )

    if isinstance(
        aktualisierte_status,
        dict
    ):
        spieler[
            "status_effekte"
        ] = aktualisierte_status

    status_nach_kampf_verarbeiten()

    status_dauer_verringern(
        "kaempfe"
    )

    if ergebnis.get(
        "gewonnen",
        False
    ):
        akt1_lernerfahrung(
            "kampf_erfahrung"
        )

    if kampfwerte["bestienjaeger_pruefung"]:
        if bestienjaeger_probe_auswerten(spieler, ergebnis):
            print("Bestienjäger-Prüfung bestanden. Kehre für die bewusste Fusion zu Rika zurück.")
        else:
            print("Die Prüfungsjagd ist beendet. Für einen neuen Versuch sprich mit Rika.")

    if kampfwerte["stahlkrieger_pruefung"]:
        if stahlkrieger_probe_auswerten(spieler, ergebnis):
            print("Stahlkrieger-Prüfung bestanden. Kehre für die bewusste Fusion zu Bjorn zurück.")
        else:
            print("Die Stahlkrieger-Probe ist beendet. Bereite deine Waffe für einen neuen Versuch vor und sprich mit Bjorn.")

    if kampfwerte["glutkrieger_pruefung"]:
        if glutkrieger_probe_auswerten(spieler, ergebnis):
            print("Glutkrieger-Prüfung bestanden. Kehre für die bewusste Fusion zu Mara zurück.")
        else:
            print("Die Glutkrieger-Probe ist beendet. Für einen neuen Versuch sprich mit Mara.")

    return ergebnis


def kampf_beute_vergeben(
    gegner_typ,
    aktuelles_gold,
    *,
    jaeger_jagd=False,
    ohne_items=False
):
    beute_daten = KAMPF_BEUTE.get(
        gegner_typ
    )

    if not beute_daten:
        return aktuelles_gold

    gold_min = beute_daten.get(
        "gold_min",
        0
    )

    gold_max = beute_daten.get(
        "gold_max",
        gold_min
    )

    gefundenes_gold = random.randint(
        gold_min,
        gold_max
    )

    gefundene_items = []

    for eintrag in ([] if ohne_items else beute_daten.get(
        "items",
        []
    )):
        chance = eintrag.get(
            "chance",
            100
        )

        if jaeger_jagd is True:
            chance += jaeger_materialbonus(
                spieler, gegner_typ, eintrag["item_id"]
            )

            # Reiche Beute: gilt für Materialien aus Jagden.
            if ITEMS.get(eintrag["item_id"], {}).get("typ") == "Material":
                chance += talent_bonus(spieler, "jagd_materialchance")

        if random.randint(
            1,
            100
        ) > chance:
            continue

        item_id = eintrag[
            "item_id"
        ]

        anzahl = random.randint(
            eintrag.get(
                "min",
                1
            ),
            eintrag.get(
                "max",
                1
            )
        )

        if item_hinzufuegen(
            item_id,
            anzahl
        ):
            jagdbuch_eintragen(gegner_typ, beute=True)
            gefundene_items.append(
                (
                    item_id,
                    anzahl
                )
            )

    aktuelles_gold += gefundenes_gold

    print()

    design_text(
        "BEUTE",
        design="wissen",
        art="menue"
    )

    print()

    if gefundenes_gold > 0:
        print(
            f"- {gefundenes_gold} Gold"
        )

    for item_id, anzahl in gefundene_items:
        print(
            f"- {anzahl}x "
            f"{ITEMS[item_id]['name']}"
        )

    if (
        gefundenes_gold <= 0
        and not gefundene_items
    ):
        print(
            "Du findest nichts Brauchbares."
        )

    return aktuelles_gold

