def attribut_entwicklungen_anzeigen(
    ergebnis
):
    if not ergebnis:
        return

    for (
        verfassung_id,
        alter_wert,
        neuer_wert
    ) in ergebnis.get(
        "verfassungen",
        []
    ):
        print()

        design_text(
            "VERFASSUNG ENTWICKELT",
            design="positiv",
            art="menue"
        )

        print(
            f"{VERFASSUNG_DEFINITIONEN[verfassung_id]['name']}: "
            f"+{alter_wert} → +{neuer_wert}"
        )

    for (
        attribut_id,
        alter_wert,
        neuer_wert
    ) in ergebnis.get(
        "attribute",
        []
    ):
        print()

        design_text(
            "ATTRIBUT ENTWICKELT",
            design="positiv",
            art="menue"
        )

        print()

        print(
            f"{ATTRIBUT_DEFINITIONEN[attribut_id]['name']}: "
            f"{alter_wert} → {neuer_wert}"
        )

    attribut_id = ergebnis.get(
        "attribut"
    )

    if attribut_id not in ATTRIBUT_DEFINITIONEN:
        return

    if (
        attribut_id == "uebersinnliches"
        and spieler["attribute"][
            attribut_id
        ] == 0
    ):
        return

    print()

    print(
        f"{ATTRIBUT_DEFINITIONEN[attribut_id]['name']}: "
        f"{spieler['attribut_fortschritt'][attribut_id]}/"
        f"{attribut_schwelle(attribut_id)} "
        "bis zur nächsten Stufe"
    )

    gepraegt = [
        VERFASSUNG_DEFINITIONEN[verfassung_id]["name"]
        for verfassung_id in ergebnis.get(
            "gepraegt",
            []
        )
    ]

    if gepraegt:
        print(
            "Geprägt: "
            + ", ".join(gepraegt)
        )


