def reise_bedingung_erfuellt(bedingung):
    if not bedingung:
        return True

    if not isinstance(
        bedingung,
        dict
    ):
        return False

    typ = bedingung.get(
        "typ"
    )

    if typ in (
        "alle",
        "eine"
    ):
        bedingungen = bedingung.get(
            "bedingungen",
            []
        )

        if not bedingungen:
            return False

        ergebnisse = [
            reise_bedingung_erfuellt(
                einzelne_bedingung
            )
            for einzelne_bedingung
            in bedingungen
        ]

        if typ == "alle":
            return all(
                ergebnisse
            )

        return any(
            ergebnisse
        )

    if typ == "nicht":
        einzelne_bedingung = bedingung.get(
            "bedingung"
        )

        if not einzelne_bedingung:
            return False

        return not reise_bedingung_erfuellt(
            einzelne_bedingung
        )

    if typ == "besonderer_fund_status":
        return besonderer_fund_status(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "weg_status":
        return weg_status(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "quest_status":
        return spieler.get(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "quest_status_in":
        return spieler.get(
            bedingung.get("id")
        ) in bedingung.get(
            "werte",
            []
        )

    if typ in (
        "spieler_wert_min",
        "spieler_wert_max"
    ):
        wert = spieler_pruefwert(
            bedingung.get("id")
        )

        grenze = bedingung.get(
            "grenze"
        )

        if not isinstance(
            wert,
            (int, float)
        ):
            return False

        if not isinstance(
            grenze,
            (int, float)
        ):
            return False

        if typ == "spieler_wert_min":
            return wert >= grenze

        return wert <= grenze

    return False

def reise_festes_ereignis_verfuegbar(
    reise_daten,
    schritt
):
    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    ausgeloest = reise_daten.get(
        "ausgeloeste_ereignisse",
        []
    )

    dauerhaft_erlebt = spieler.get(
        "reise_ereignisse",
        []
    )

    for ereignis in strecken_daten.get(
        "ereignisse",
        []
    ):
        ereignis_id = ereignis.get(
            "id"
        )

        if not ereignis_id:
            continue

        if ereignis.get(
            "schritt"
        ) != schritt:
            continue

        ereignis_richtung = ereignis.get(
            "richtung"
        )

        if (
            ereignis_richtung
            and ereignis_richtung != richtung
        ):
            continue

        if ereignis_id in ausgeloest:
            continue

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            in dauerhaft_erlebt
        ):
            continue

        if not reise_bedingung_erfuellt(
            ereignis.get(
                "bedingung"
            )
        ):
            continue

        return True

    return False



def reise_ereignisse_pruefen(
    reise_daten,
    schritt
):
    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    ausgeloest = reise_daten.setdefault(
        "ausgeloeste_ereignisse",
        []
    )

    dauerhaft_erlebt = spieler.setdefault(
        "reise_ereignisse",
        []
    )

    ereignis_angezeigt = False

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    for ereignis in strecken_daten.get(
        "ereignisse",
        []
    ):
        ereignis_id = ereignis.get(
            "id"
        )

        if not ereignis_id:
            continue

        if ereignis.get(
            "schritt"
        ) != schritt:
            continue

        ereignis_richtung = ereignis.get(
            "richtung"
        )

        if (
            ereignis_richtung
            and ereignis_richtung != richtung
        ):
            continue

        if ereignis_id in ausgeloest:
            continue

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            in dauerhaft_erlebt
        ):
            continue

        if not reise_bedingung_erfuellt(
            ereignis.get(
                "bedingung"
            )
        ):
            continue

        ausgeloest.append(
            ereignis_id
        )

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            not in dauerhaft_erlebt
        ):
            dauerhaft_erlebt.append(
                ereignis_id
            )

        aktion = ereignis.get(
            "aktion"
        )

        if aktion == "hilda_karren":
            ereignis_angezeigt = bool(
                hilda_karren_ereignis()
            )

            continue

        print()

        titel = ereignis.get(
            "titel"
        )

        if titel:
            design_text(
                titel,
                design=ereignis.get(
                    "design",
                    "wissen"
                ),
                art="menue"
            )

            print()

        zeilen = ereignis.get(
            "text",
            []
        )

        for nummer, zeile in enumerate(
            zeilen
        ):
            text_ausgeben(
                zeile
            )

            if nummer < len(zeilen) - 1:
                print()

        warte_auf_taste(
            ereignis.get(
                "weiter_text",
                "Weiterreisen"
            )
        )

        ereignis_angezeigt = True

    return ereignis_angezeigt

