def letzthafen_wrackstrand_jagd():
    if not spieler.get("wrackstrand_eingefuehrt", False):
        ort_titel("Letzthafen - Wrackstrand")
        text_ausgeben(
            "Ein schmaler Pfad führt vom Ende des Klippenwegs zwischen den "
            "Felsen hinab. Unten liegt ein steiniger Strand, übersät mit "
            "Treibholz und den Rippen eines alten Bootes."
        )
        print()
        text_ausgeben(
            "Zwischen den Wrackteilen klappert etwas über die Steine. "
            "Weiter hinten durchwühlt jemand das Strandgut."
        )
        spieler["wrackstrand_eingefuehrt"] = True
        warte_auf_taste("Weiter")

    spur_untersucht = False

    while spieler.get("spiel_laeuft", True):
        ort_titel("Letzthafen - Wrackstrand")

        lebenspunkte = spieler["lebenspunkte"]
        print(f"Lebenspunkte: {lebenspunkte}/100")

        if lebenspunkte <= 35:
            design_text(
                "Du bist schwer verletzt. Eine Jagd ist jetzt besonders "
                "gefährlich. Öffne das Inventar, um dich zu versorgen, "
                "oder steig zurück zum Klippenweg.",
                design="warnung",
                art="menue"
            )

        print()

        spuren_erkannt = (
            spur_untersucht
            or spieler_pruefung(
                "wahrnehmung",
                3 - talent_bonus(spieler, "wildspur_schwelle")
            )
        )

        if spuren_erkannt:
            print("Du kannst die Spuren im Sand unterscheiden.")
            print()
            print("1. Den Schleifspuren zwischen den Wrackteilen folgen - Gezeitenkrebs [1 Schritt]")
            print("2. Den Stiefelabdrücken zum Bootswrack folgen - Wrackplünderer [1 Schritt]")
        else:
            print("Die Flut hat die meisten Spuren verwischt.")
            print()
            print("1. Einer verwischten Spur folgen [1 Schritt]")
            print("2. Den Strand genauer absuchen [1 zusätzlicher Schritt]")

        print("3. Inventar öffnen")
        print("4. Zurück zum Klippenweg")
        print()
        print("[Schritt]: Blutung, Gift und Mahlzeit-Wirkungen laufen dabei einen Schritt weiter.")

        auswahl = eingabe_menu(1, 4, sonder_tasten=())

        if auswahl == 4:
            return

        if auswahl == 3:
            inventar()
            continue

        if not spuren_erkannt and auswahl == 2:
            if not status_schritte_abschliessen():
                return

            spur_untersucht = True
            text_ausgeben(
                "Du suchst den Strand ab. Zwischen den Wrackteilen ziehen sich "
                "breite Schleifspuren, Stiefelabdrücke führen zum alten Boot. "
                "Jetzt kannst du gezielt einer Spur folgen."
            )
            warte_auf_taste("Spur wählen")
            continue

        if not spieler.get("waffe"):
            design_text(
                "Rüste im Inventar eine Waffe aus, bevor du jagst.",
                design="warnung",
                art="menue"
            )
            warte_auf_taste("Zurück")
            continue

        if spuren_erkannt:
            gegner_typ = "Gezeitenkrebs" if auswahl == 1 else "Wrackplünderer"
        else:
            gegner_typ = random.choice(("Gezeitenkrebs", "Wrackplünderer"))

        if not status_schritte_abschliessen():
            return

        gegner_typ = revierherr_pruefen("wrackstrand", gegner_typ)

        if gegner_typ is None:
            continue

        print()

        if gegner_typ == "Einscherer":
            text_ausgeben(
                "Der Einscherer hebt seine gewaltige Schere."
            )
        elif gegner_typ == "Gezeitenkrebs":
            text_ausgeben(
                "Unter einer Planke schiebt sich ein Krebs hervor, so groß wie "
                "ein Hund. Seine Scheren klappern über die Steine."
            )
        else:
            text_ausgeben(
                "Am Bootswrack richtet sich ein Mann mit einem Haken auf. "
                "Über seiner Schulter hängt ein zusammengerolltes Netz."
            )

        print()

        kampf_ergebnis = kampf_starten(
            lebenspunkte=spieler["lebenspunkte"],
            heiltraenke=spieler["heiltränke"],
            waffe=spieler["waffe"],
            gegner_typ=gegner_typ,
            kampf_situation={
                "gebiet": "Wald",
                "umgebung": "Lichtung",
                "tageszeit": spieler.get("tageszeit", "Tag"),
                "wetter": spieler.get("wetter", "Klar")
            }
        )

        spieler["lebenspunkte"] = kampf_ergebnis["lebenspunkte"]
        spieler["heiltränke"] = kampf_ergebnis["heiltraenke"]

        if kampf_ergebnis.get("gewonnen", False):
            spieler["besiegte_gegner"] += 1
            print()
            print("-" * 34)
            design_text(
                "JAGD ERFOLGREICH",
                design="positiv",
                art="ereignis"
            )
            spieler["gold"] = kampf_beute_vergeben(
                gegner_typ,
                spieler["gold"],
                jaeger_jagd=gegner_typ == "Gezeitenkrebs",
                ohne_items=kampf_ergebnis.get("gegner_verschont", False)
            )
            print()
            print(f"Lebenspunkte: {spieler['lebenspunkte']}")
            print("-" * 34)
            warte_auf_taste("Zum Wrackstrand")

        elif kampf_ergebnis.get("besiegt", False):
            print()
            design_text(
                "Game Over",
                design="gefahr",
                art="menue"
            )
            spieler["spiel_laeuft"] = False
            return

        elif kampf_ergebnis.get("geflohen", False):
            print()
            text_ausgeben(
                "Du brichst die Jagd ab und steigst zum Klippenweg hinauf.",
                art="menue"
            )
            warte_auf_taste("Zum Klippenweg")
            return


