def speicherplatz_auswahl_laden():
    while True:
        ort_titel(
            "Spiel laden"
        )

        for slot in range(
            1,
            ANZAHL_SPEICHER_SLOTS + 1
        ):
            print(
                speicherplatz_text(
                    slot
                )
            )

        zurueck_option = (
            ANZAHL_SPEICHER_SLOTS + 1
        )

        print(
            f"{zurueck_option}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_option,
            sonder_tasten=()
        )

        if auswahl == zurueck_option:
            return None

        if not os.path.exists(
            speicherdatei_pfad(
                auswahl
            )
        ):
            print()
            print(
                "Dieser Speicherplatz ist leer."
            )

            warte_auf_taste(
                "Zurück"
            )

            continue

        return auswahl

def speicherplatz_auswahl_loeschen():
    while True:
        ort_titel(
            "Spielstand löschen"
        )

        for slot in range(
            1,
            ANZAHL_SPEICHER_SLOTS + 1
        ):
            print(
                speicherplatz_text(
                    slot
                )
            )

        zurueck_option = (
            ANZAHL_SPEICHER_SLOTS + 1
        )

        print(
            f"{zurueck_option}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_option,
            sonder_tasten=()
        )

        if auswahl == zurueck_option:
            return

        speicher_datei = (
            speicherdatei_pfad(
                auswahl
            )
        )

        if not os.path.exists(
            speicher_datei
        ):
            print()

            print(
                "Dieser Speicherplatz ist bereits leer."
            )

            warte_auf_taste(
                "Zurück"
            )

            continue

        ort_titel(
            "Spielstand löschen"
        )

        design_text(
            "SPIELSTAND LÖSCHEN?",
            design="warnung",
            art="menue"
        )

        print()

        print(
            speicherplatz_text(
                auswahl
            )
        )

        print()

        print(
            "Dieser Vorgang kann nicht "
            "rückgängig gemacht werden."
        )

        menue_trenner()
        print()

        print(
            "1. Spielstand löschen"
        )

        print(
            "2. Abbrechen"
        )

        bestaetigung = eingabe_menu(
            1,
            2,
            sonder_tasten=()
        )

        if bestaetigung == 2:
            continue

        try:
            os.remove(
                speicher_datei
            )

        except OSError as fehler:
            print()

            design_text(
                "LÖSCHEN FEHLGESCHLAGEN",
                design="gefahr",
                art="menue"
            )

            print()

            print(
                f"Fehler: {fehler}"
            )

            warte_auf_taste(
                "Zurück"
            )

            continue

        print()

        design_text(
            "SPIELSTAND GELÖSCHT",
            design="positiv",
            art="menue"
        )

        warte_auf_taste(
            "Weiter"
        )

