def hauptmenue_starten():
    global spieler
    global AKTIVER_SPEICHER_SLOT

    einstellungen_laden()

    alten_spielstand_importieren()

    spieler = None
    neues_spiel = False
    prolog_ueberspringen = False

    while spieler is None:

        hauptmenue_auswahl = hauptmenue()

        if hauptmenue_auswahl == 1:
            slot = (
                speicherplatz_auswahl_neues_spiel()
            )

            if slot is None:
                continue

            prolog_auswahl = prolog_startauswahl()

            if prolog_auswahl == 3:
                continue

            prolog_ueberspringen = (
                prolog_auswahl == 2
            )

            while True:
                name = input(
                    "Wie ist dein Name? "
                ).strip()

                if name:
                    break

                print(
                    "Bitte gib einen Namen ein."
                )

            AKTIVER_SPEICHER_SLOT = slot

            spieler = neuer_spieler(name)

            start_veranlagung_waehlen()

            neues_spiel = True

            if prolog_ueberspringen:
                spieler["prolog_status"] = "prolog_abgeschlossen"
                spieler["akt"] = "AKT 1"
                spieler["ort"] = "Eichenruh"

                spieler["prolog_besuchte_orte"] = {
                    "gasthaus": True,
                    "schmiede": True,
                    "marktplatz": True
                }

                spieler["prolog_joris_hinweise"] = {
                    "mara": True,
                    "tomas": True
                }

                spieler["koehler_nachricht_bjorn"] = "offen"

                item_hinzufuegen(
                    "holz",
                    3
                )

                spieler["prolog_skip_startwaffe"] = True
                spieler["prolog_uebersprungen"] = True


            if (
                DEV_TEST_ITEMS
                and not getattr(
                    sys,
                    "frozen",
                    False
                )
            ):
                spieler[
                    "lebenspunkte"
                ] = 50

                item_hinzufuegen(
                    "apfel",
                    2
                )

                item_hinzufuegen(
                    "brot",
                    1
                )

            if (
                DEV_TEST_KOCHEN
                and not getattr(
                    sys,
                    "frozen",
                    False
                )
            ):
                spieler[
                    "prolog_status"
                ] = "prolog_abgeschlossen"

                spieler[
                    "gold"
                ] = 30

                spieler[
                    "akt"
                ] = "AKT 1"

                spieler[
                    "rezepte_gelernt"
                ] = []

        elif hauptmenue_auswahl == 2:
            slot = (
                speicherplatz_auswahl_laden()
            )

            if slot is not None:
                spieler = spiel_laden(
                    slot
                )

        elif hauptmenue_auswahl == 3:
            speicherplatz_auswahl_loeschen()

        elif hauptmenue_auswahl == 4:
            optionen()

        elif hauptmenue_auswahl == 5:
            print("Bis bald!")
            raise SystemExit

    if neues_spiel:
        if (
            not DEV_MODUS
            and not prolog_ueberspringen
        ):
            spiel_intro()

        if DEV_MODUS:
            spieler["prolog_status"] = "prolog_abgeschlossen"
            spieler["akt"] = "AKT 1"

            spieler["ort"] = "Gasthaus"

            item_hinzufuegen(
                "altes_kartenstueck"
            )
            weg_entdecken(
                "alter_seitenpfad"
            )

            weg_als_gesehen_markieren(
                "alter_seitenpfad"
            )

            spieler["lebenspunkte"] = 40

            ausruestung_setzen(
                "waffe",
            {
                "name": "Schweres Handbeil",
                "min_schaden": 8,
                "max_schaden": 16,
                "verkaufswert": 5,
                "typ": "Beil",
                "wendigkeit": 1,
                "parade": 1,
                "reichweite": 1
                    }
                )

            item_hinzufuegen(
                "holz",
                6
            )

            ort_nachricht_setzen(
                "DEV-Testmodus aktiv.",
                "Du startest direkt in Maras Gasthaus."
            )

        else:
            ort_nachricht_setzen(
                "Du öffnest die Augen. Das erste Licht fällt auf die Dielen.",
                "Draußen schlägt Metall auf Metall. Ein Wagen rumpelt über die Straße. Vom Markt her sind Stimmen zu hören.",
                "Ein Morgen wie viele zuvor."
            )


