def talente_umlernen():
    kosten = umlernkosten(spieler)
    ort_titel("Talente neu wählen")
    print("Alle gewählten Talente werden zurückgesetzt. Danach wählst du jede Stufe neu.")
    print(f"Kosten: {kosten} Gold (vorhanden: {spieler['gold']})")
    print("Jede weitere Neuwahl kostet doppelt so viel.")

    if spieler["gold"] < kosten:
        print("Dafür reicht dein Gold nicht.")
        warte_auf_taste("Zurück")
        return

    print()
    print("1. Ja, Talente zurücksetzen")
    print("2. Nein, zurück")

    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    spieler["gold"] -= kosten
    talente_zuruecksetzen(spieler)
    design_text(
        "Talente zurückgesetzt. Wähle sie jetzt neu.",
        design="positiv",
        art="menue"
    )
    warte_auf_taste("Weiter")


def talent_stufe_menue(stufe):
    while spieler.get("spiel_laeuft", True):
        ort_titel(f"Talente – Stufe {stufe}")
        gewaehlt = talent_der_stufe(spieler, stufe)
        talent_ids = talente_der_stufe(stufe)

        for talent_id in talent_ids:
            daten = TALENTE[talent_id]
            marke = " [gewählt]" if talent_id == gewaehlt else ""
            print(f"{TALENT_RICHTUNGEN[daten['richtung']]}: {daten['name']}{marke}")
            print(f"  {daten['beschreibung']}")

        print()

        if level_fortschritt(spieler)["level"] < stufe:
            print(f"Diese Stufe wird mit Level {stufe} frei.")
            warte_auf_taste("Zurück")
            return

        if gewaehlt is not None:
            print("Auf dieser Stufe hast du bereits gewählt. Umlernen kannst du in Eichenruh.")
            warte_auf_taste("Zurück")
            return

        print("Wähle eines der drei Talente.")
        print()

        for nummer, talent_id in enumerate(talent_ids, start=1):
            print(f"{nummer}. {TALENTE[talent_id]['name']} wählen")

        zurueck = len(talent_ids) + 1
        print(f"{zurueck}. Zurück")

        auswahl = eingabe_menu(1, zurueck, sonder_tasten=())

        if auswahl == zurueck:
            return

        talent_id = talent_ids[auswahl - 1]
        daten = TALENTE[talent_id]
        hindernis = talent_lernhindernis(spieler, talent_id)

        if hindernis:
            print(hindernis)
            warte_auf_taste("Zurück")
            continue

        print(f"{daten['name']} wählen? Ändern kannst du die Wahl später gegen Gold in Eichenruh.")
        print()
        print("1. Ja, Talent wählen")
        print("2. Nein, zurück")

        if eingabe_menu(1, 2, sonder_tasten=()) == 2:
            continue

        if talent_lernen(spieler, talent_id):
            design_text(
                f"Talent gewählt: {daten['name']}",
                design="positiv",
                art="menue"
            )
        else:
            print("Das Talent konnte nicht gewählt werden.")

        warte_auf_taste("Weiter")
        return


def talentmenue():
    while spieler.get("spiel_laeuft", True):
        ort_titel("Talente")
        fortschritt = level_fortschritt(spieler)
        punkte = talentpunkte_verfuegbar(spieler)

        print(f"Level: {fortschritt['level']}")

        if fortschritt["aufstiegskosten"] is None:
            print(f"Gesamt-EXP: {fortschritt['gesamt_exp']}")
            print("Weitere Level sind noch nicht eingerichtet.")
        else:
            print(
                f"EXP zum nächsten Level: {fortschritt['exp_im_level']}"
                f"/{fortschritt['aufstiegskosten']}"
            )

        print(f"Freie Talentpunkte: {punkte}")
        print("Auf jeder Stufe wählst du eines von drei Talenten: Klinge, Pfad oder Werkstatt.")
        print()

        optionen = []

        for stufe in range(1, TALENT_STUFEN + 1):
            gewaehlt = talent_der_stufe(spieler, stufe)

            if gewaehlt is not None:
                text = TALENTE[gewaehlt]["name"]
            elif fortschritt["level"] >= stufe:
                text = "offen – Talent wählen [!]"
            else:
                text = f"ab Level {stufe}"

            optionen.append(("stufe", stufe))
            print(f"{len(optionen)}. Stufe {stufe}: {text}")

        umlernen_moeglich = (
            spieler.get("ort") == "Eichenruh"
            and not reise_aktiv()
            and any(
                talent_der_stufe(spieler, stufe) is not None
                for stufe in range(1, TALENT_STUFEN + 1)
            )
        )

        if umlernen_moeglich:
            optionen.append(("umlernen", None))
            print(f"{len(optionen)}. Talente neu wählen ({umlernkosten(spieler)} Gold)")

        optionen.append(("klasse", None))
        print(f"{len(optionen)}. Grundklasse ansehen / wählen")
        optionen.append(("berufe", None))
        print(f"{len(optionen)}. Berufe und Praxis ansehen")
        optionen.append(("zurueck", None))
        print(f"{len(optionen)}. Zurück")

        auswahl = eingabe_menu(
            1, len(optionen), sonder_tasten=()
        )
        typ, wert = optionen[auswahl - 1]

        if typ == "zurueck":
            return
        if typ == "klasse":
            klassenmenue()
            continue
        if typ == "berufe":
            berufsmenue()
            continue
        if typ == "umlernen":
            talente_umlernen()
            continue

        talent_stufe_menue(wert)


def status():
    ort_titel("Status")

    attribut_system_sicherstellen()

    print(f"Name: {spieler['name']}")
    klasse_id = grundklasse_holen(spieler)
    klassen_name = (
        KLASSEN.get(klasse_id, {}).get("name", klasse_id)
        if klasse_id is not None else "Noch nicht gewählt"
    )
    print(f"Grundklasse: {klassen_name}")
    hybrid_name = hybrid_name_holen(spieler)
    if hybrid_name:
        print(f"Aktiver Hybrid: {hybrid_name}")
        if hybrid_aktiv_holen(spieler) == "stahlkrieger":
            print("Hybridfähigkeiten: Ambossstand [A], Schmiedehieb [S], veredelte Waffenpflege.")
        elif hybrid_aktiv_holen(spieler) == "glutkrieger":
            print("Hybridfähigkeiten: Kampfportion [G], Kraftschub [B], Nachwärme.")
            print("Kampfportion: " + ("vorbereitet" if glutkrieger_portion_holen(spieler) else "noch vorzubereiten"))
        else:
            print("Hybridfähigkeiten: Beute studieren [V], gezielter Jagdhieb [J], Jagdinstinkt.")
    if klasse_id == "kaempfer":
        print("Kriegerfähigkeit: Deckung halten [K im Kampf]")
    elif klasse_id == "spaeher":
        print("Späherfähigkeit: Lücke nutzen [L im Kampf]")
    elif klasse_id == "gelehrter":
        print("Gelehrtenfähigkeit: Muster erkennen [M im Kampf]")
    elif klasse_id == "magier":
        print("Magierfähigkeit: Resonanzstoß [R im Kampf, 3 Ladungen pro Kampf]")

    fortschritt = level_fortschritt(spieler)

    print(f"Level: {fortschritt['level']}")
    print(f"Gesamt-EXP: {fortschritt['gesamt_exp']}")

    if fortschritt["aufstiegskosten"] is not None:
        print(
            f"EXP zum nächsten Level: {fortschritt['exp_im_level']}"
            f"/{fortschritt['aufstiegskosten']}"
            f" (noch {fortschritt['exp_bis_aufstieg']})"
        )
    else:
        print("Weitere Level sind noch nicht eingerichtet.")

    print(
        f"Freie Talentpunkte: "
        f"{talentpunkte_verfuegbar(spieler)}"
    )
    print()

    print(f"Lebenspunkte: {spieler['lebenspunkte']}")
    print(f"Gold: {spieler['gold']}")
    print(f"Diamanten: {spieler['diamanten']}")
    print(f"Besiegte Gegner: {spieler['besiegte_gegner']}")
    print(f"Spielzeit: {spielzeit_text()}")

    print()

    design_text(
        "Attribute und Verfassungen",
        design="wissen",
        art="menue"
    )

    uebersinnlich_erwacht = spieler["attribute"]["uebersinnliches"] > 0

    for attribut_id, verfassungen in STATUS_VERFASSUNGEN:
        attribut_name = ATTRIBUT_DEFINITIONEN[attribut_id]["name"]

        if attribut_id == "uebersinnliches" and not uebersinnlich_erwacht:
            print(f"{attribut_name}: ???")
            continue

        werte = ", ".join(
            f"{VERFASSUNG_DEFINITIONEN[verfassung_id]['name']} "
            f"{verfassung_pruefwert_basis(verfassung_id)}"
            for verfassung_id in verfassungen
        )
        print(
            f"{attribut_name} {spieler['attribute'][attribut_id]}: {werte}"
        )

    if uebersinnlich_erwacht and spieler.get(
        "waldwaechter_schwelle_erlebt",
        False
    ):
        print(
            "Seit der Waldlichtung nimmst du manchmal "
            "Zusammenhänge wahr, bevor du sie bewusst erkennst."
        )

    print()

    aktuelle_waffe = spieler.get("waffe")

    if aktuelle_waffe:
        print(
            f"Waffe: {aktuelle_waffe['name']} "
            f"({aktuelle_waffe['min_schaden']}-"
            f"{aktuelle_waffe['max_schaden']} Schaden)"
        )

    else:
        print("Waffe: Keine")

    menue_trenner()
    print()
    print("1. Verfassungen im Detail")
    print("2. Zurück")

    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        status_verfassungen_details(uebersinnlich_erwacht)


STATUS_VERFASSUNGEN = (
    ("koerper", ("staerke", "ausdauer", "geschick", "zaehigkeit")),
    ("geist", ("wissen", "wahrnehmung", "willenskraft", "empathie")),
    ("uebersinnliches", ("sensibilitaet", "resonanz", "kontrolle", "anker"))
)


def verfassung_pruefwert_basis(verfassung_id):
    attribut_id = VERFASSUNG_DEFINITIONEN[verfassung_id]["attribut"]

    return (
        spieler["attribute"].get(attribut_id, 0)
        + spieler["verfassungen"].get(verfassung_id, 0)
    )


def status_verfassungen_details(uebersinnlich_erwacht):
    ort_titel("Status - Verfassungen")
    print(
        "Der Wert ist dein Prüfwert für Proben. In Klammern: Unterschied "
        "zum Attribut. Prägung: Fortschritt bis zur nächsten Stufe."
    )

    for attribut_id, verfassungen in STATUS_VERFASSUNGEN:
        if attribut_id == "uebersinnliches" and not uebersinnlich_erwacht:
            continue

        print()
        design_text(
            ATTRIBUT_DEFINITIONEN[attribut_id]["name"],
            design="wissen",
            art="menue"
        )

        for verfassung_id in verfassungen:
            verfassung_status_anzeigen(verfassung_id)

    warte_auf_taste()

def orte_belegt():
    ort = spieler.get("ort")
    besucht = set(spieler.get("besuchte_orte", []))
    if ort:
        besucht.add(ort)
    prolog_orte = spieler.get("prolog_besuchte_orte", {})
    knoten = spieler.get("wald_erforschung", {}).get("besuchte_knoten", [])
    letzthafen_daten = spieler.get("letzthafen_status", {})
    bereiche = letzthafen_daten.get("besuchte_bereiche", [])

    koehlerei = (
        "Köhlerei" in besucht
        or spieler.get("prolog_rueckweg_sicher") is True
        or spieler.get("brandschneise_eingefuehrt") is True
    )
    lichtung = (
        spieler.get("waldwaechter_eindruck_gezeigt") is True
        or spieler.get("waldwaechter_besiegt") is True
    )
    belege = {
        "ort_eichenruh": True,
        "ort_gasthaus": prolog_orte.get("gasthaus") is True or "Gasthaus" in besucht,
        "ort_schmiede": prolog_orte.get("schmiede") is True or "Schmiede" in besucht,
        "ort_marktplatz": prolog_orte.get("marktplatz") is True or "Marktplatz" in besucht,
        "ort_wald": "Wald" in besucht or bool(knoten) or koehlerei or lichtung,
        "ort_wildspur": "wildspur" in knoten,
        "ort_wegstein": "wegstein" in knoten or spieler.get("wald_wegstein_untersucht") is True,
        "ort_versunkene_steine": "versunkene_steine" in knoten,
        "ort_wegstation": spieler.get("wegstation_status", {}).get("entdeckt") is True,
        "ort_lichtung": lichtung,
        "ort_koehlerei": koehlerei,
        "ort_alter_koehlerpfad": spieler.get("koehlerpfad_betreten") is True,
        "ort_brandschneise": spieler.get("brandschneise_eingefuehrt") is True,
        "ort_verlassenes_dorf": spieler.get("verlassenes_dorf_eindruck_gezeigt") is True,
        "ort_alte_schmiede": spieler.get("alte_schmiede_eindruck_gezeigt") is True,
        "ort_oros": (
            spieler.get("universitaet_oros_eindruck_gezeigt") is True
            or "universitaet_oros" in besucht
        ),
        "ort_oros_halle": spieler.get("oros_zentrale_halle_eindruck_gezeigt") is True,
        "ort_oros_lehrhallen": spieler.get("oros_lehrhallen_eindruck_gezeigt") is True,
        "ort_oros_forschung": spieler.get("oros_forschungsraeume_eindruck_gezeigt") is True,
        "ort_oros_archiv": spieler.get("oros_archiv_eindruck_gezeigt") is True,
        "ort_felsterrassen": spieler.get("felsterrassen_eingefuehrt") is True,
        "ort_letzthafen": letzthafen_daten.get("angekommen") is True or "Letzthafen" in besucht,
        "ort_wrackstrand": spieler.get("wrackstrand_eingefuehrt") is True,
    }
    for bereich_id in (
        "letztes_licht", "elian_werkstatt", "gezeitensteg", "haus_der_listen",
        "namenstein", "edda_haus", "altes_leuchtfeuer", "klippenweg"
    ):
        belege["ort_" + bereich_id] = bereich_id in bereiche
    for weg_id in (
        "koenigsring", "alter_seitenpfad", "pfad_des_vergessens", "faden_der_erinnerung"
    ):
        belege["weg_" + weg_id] = weg_status(weg_id) == "entdeckt"

    return {eintrag_id for eintrag_id, belegt in belege.items() if belegt}


def sammlungen_abgleichen():
    besessen = orte_belegt()

    for item_id, anzahl in spieler.get("inventar_items", {}).items():
        if isinstance(anzahl, int) and anzahl > 0:
            besessen.add(item_id)

    gegenstaende = list(spieler.get("ausruestungs_inventar", []))
    ausruestung = spieler.get("ausruestung", {})
    if isinstance(ausruestung, dict):
        gegenstaende += list(ausruestung.values())
    for gegenstand in gegenstaende:
        if isinstance(gegenstand, dict) and gegenstand.get("id"):
            besessen.add(gegenstand["id"])

    waffen = list(spieler.get("waffen_inventar", []))
    waffen.append(spieler.get("waffe"))
    for waffe in waffen:
        if isinstance(waffe, dict) and waffe.get("name"):
            besessen.add(waffe["name"])

    for sammlung_id, sammlung in SAMMLUNGEN.items():
        neu = [
            eintrag_id
            for eintrag_id, _ in sammlung["eintraege"]
            if eintrag_id in besessen
            and eintrag_id not in spieler.get("sammlungen", {}).get(sammlung_id, [])
        ]
        if neu:
            spieler.setdefault("sammlungen", {}).setdefault(sammlung_id, []).extend(neu)


SAMMLUNGS_GRUPPEN = (
    ("Orte", ("orte_eichenruh", "orte_oros", "orte_letzthafen", "wege")),
    ("Gegenstände", ("materialien", "handwerk"))
)


def sammlungen_uebersicht():
    gruppen = []
    for gruppen_name, sammlung_ids in SAMMLUNGS_GRUPPEN:
        eintraege = []
        for sammlung_id in sammlung_ids:
            sammlung = SAMMLUNGEN[sammlung_id]
            gesammelt = spieler.get("sammlungen", {}).get(sammlung_id, [])
            eintraege.append((
                sammlung["name"],
                [
                    (eintrag_id in gesammelt, name)
                    for eintrag_id, name in sammlung["eintraege"]
                ]
            ))
        gruppen.append((gruppen_name, eintraege))

    gelernt = spieler.get("rezepte_gelernt", [])
    gruppen.append((
        "Rezepte",
        [
            (
                sammlung["name"],
                [
                    (rezept_id in gelernt, REZEPTE[rezept_id]["name"])
                    for rezept_id in sammlung["rezepte"]
                ]
            )
            for sammlung in REZEPT_SAMMLUNGEN.values()
        ]
    ))
    return gruppen


