def erfolge_sammlungen():
    while True:
        ort_titel("Erfolge - Sammlungen")

        sammlungen_abgleichen()

        auswahl_liste = []
        for gruppen_name, eintraege in sammlungen_uebersicht():
            design_text(gruppen_name, design="wissen", art="menue")
            for name, inhalt in eintraege:
                auswahl_liste.append((name, inhalt))
                anzahl = sum(1 for belegt, _ in inhalt if belegt)
                print(f"{len(auswahl_liste)}. {name} ({anzahl}/{len(inhalt)})")
            print()

        print(f"{len(auswahl_liste) + 1}. Zurück")

        auswahl = eingabe_menu(1, len(auswahl_liste) + 1, sonder_tasten=())

        if auswahl == len(auswahl_liste) + 1:
            return

        sammlung_anzeigen(*auswahl_liste[auswahl - 1])


