def jagdbuch_eintragen(gegner_typ, verhalten=(), beute=False):
    if gegner_typ not in JAGDBUCH:
        return

    buch = spieler.setdefault("jagdbuch", {})
    eintrag = buch.setdefault(
        gegner_typ,
        {"gesehen": True, "verhalten": [], "beute": False}
    )

    for kennung in verhalten:
        if (
            kennung in JAGDBUCH[gegner_typ]["verhalten"]
            and kennung not in eintrag["verhalten"]
        ):
            eintrag["verhalten"].append(kennung)

    if beute:
        eintrag["beute"] = True


JAGDBUCH_GEBIETE = (
    ("Wald und Wege", ("Wolf", "Keiler", "Bandit", "Graupelz")),
    ("Brandschneise", ("Glutsalamander", "Kohlenschmuggler", "Aschenkönig")),
    ("Felsterrassen", ("Schieferpanzer", "Kreischer", "Steinvater")),
    ("Wrackstrand", ("Gezeitenkrebs", "Wrackplünderer", "Einscherer")),
    ("Pfad des Vergessens", ("Rudelloser Wolf", "Echohirsch", "Blasser Hirsch")),
    ("Die TIEFEN", ("Schachtflatterer", "Schachtkriecher", "Blindmolch", "Schachtspinner"))
)


