        if not eintrag:
            print("? ???")
            print()
            continue

        design_text(gegner_typ, design="wissen", art="menue")
        print(daten["beschreibung"])

        for kennung, text in daten["verhalten"].items():
            if kennung in eintrag.get("verhalten", []):
                print(f"- {text}")
