def rezept_fehlende_zutaten(rezept):
    return system_rezept_fehlende_zutaten(
        spieler,
        rezept
    )


def rezept_kann_gekocht_werden(rezept):
    return system_rezept_kann_gekocht_werden(
        spieler,
        rezept
    )

def koch_wirkung_anzeigen(rezept, einzug=""):
    gericht = ITEMS[rezept["ergebnis"]]
    kueche_bonus = gute_kueche_bonus(gericht)
    heilung = gericht.get("heilung", 0)
    if heilung > 0:
        heilung += kueche_bonus
    print(f"{einzug}Beim Essen: bis zu {heilung} Leben heilen.")
    for effekt in gericht.get("status_effekte", []):
        definition = STATUS_EFFEKTE.get(effekt["id"], {})
        dauer = effekt.get("dauer", definition.get("standard_dauer", 0))
        einheit = effekt.get("einheit", definition.get("standard_einheit"))
        dauer = gute_kueche_dauer(dauer, einheit, kueche_bonus)
        einheiten = {"schritte": "Schritte", "runden": "Kampfrunden", "kaempfe": "Kämpfe"}
        modifikatoren = definition.get("modifikatoren", {})
        werte = []
        if "wahrnehmung" in modifikatoren:
            werte.append(f"{modifikatoren['wahrnehmung']:+} Wahrnehmung")
        if "schaden_bonus" in modifikatoren:
            werte.append(f"{modifikatoren['schaden_bonus']:+} Waffenschaden")
        wirkung = ", ".join(werte) or definition.get("beschreibung", "Zusätzlicher Effekt")
        name = definition.get("name", effekt["id"])
        print(f"{einzug}{name}: {wirkung} für {dauer} {einheiten.get(einheit, einheit)}.")


def koch_vorratskueche_anzeigen():
    if not koch_vorratskueche_gelernt(spieler):
        return
    stand = koch_portionenstand(spieler)
    if stand is None:
        print("Vorratsküche: Der Fortschritt ist nicht lesbar; aktuell keine Zusatzportion.")
    elif stand == 3:
        print("Vorratsküche: Die nächste erfolgreiche Zubereitung ergibt eine Zusatzportion ohne weitere Zutaten.")
    else:
        print(f"Vorratsküche: noch {4 - stand} erfolgreiche Zubereitungen bis zur Zusatzportion.")



def kochen(titel="Kochen"):
    while True:
        ort_titel(titel)

        gelernte_rezepte = [
            rezept_id
            for rezept_id in spieler.get(
                "rezepte_gelernt",
                []
            )
            if rezept_id in REZEPTE
        ]

        if not gelernte_rezepte:
            print(
                "Du kennst momentan keine Rezepte."
            )

            print()
            print(
                "Vielleicht findest du irgendwo "
                "ein Kochbuch."
            )

            warte_auf_taste()
            return

        print("Die Gerichte kommen in dein Inventar. Ihre Wirkung tritt erst beim Essen ein.")
        koch_vorratskueche_anzeigen()
        print()
        print("Bekannte Rezepte:")
        print()

        for nummer, rezept_id in enumerate(gelernte_rezepte, start=1):
            rezept = REZEPTE[rezept_id]
            print(f"{nummer}. {rezept['name']}")
            zutaten = ", ".join(
                f"{anzahl}x {ITEMS[item_id]['name']} (vorhanden: {item_anzahl(item_id)})"
                for item_id, anzahl in rezept["zutaten"].items()
            )
            print("   Zutaten: " + zutaten)
            koch_wirkung_anzeigen(rezept, einzug="   ")
            menge = rezept.get("anzahl", 1) + koch_zusatzportion(spieler, rezept_id)
            print(f"   Ergebnis: {menge}x {ITEMS[rezept['ergebnis']]['name']}")
            fehlende_zutaten = rezept_fehlende_zutaten(rezept)
            if not fehlende_zutaten:
                design_text("   [Bereit]", design="positiv", art="menue")
            else:
                fehlt = ", ".join(
                    f"{anzahl}x {ITEMS[item_id]['name']}"
                    for item_id, anzahl in fehlende_zutaten
                )
                print("   [Fehlt: " + fehlt + "]")
            print()

        zurueck_nummer = (
            len(gelernte_rezepte) + 1
        )

        print()
        print(
            f"{zurueck_nummer}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        rezept_id = gelernte_rezepte[
            auswahl - 1
        ]

        rezept = REZEPTE[
            rezept_id
        ]

        ort_titel(
            rezept["name"]
        )

        ergebnis_id = rezept[
            "ergebnis"
        ]

        heilung = ITEMS[
            ergebnis_id
        ].get(
            "heilung",
            0
        )

        koch_wirkung_anzeigen(rezept)
        print("Das Gericht kommt in dein Inventar; beim Zubereiten erhältst du noch keine Wirkung.")

        print()
        print("Benötigte Zutaten:")
        print()

        for item_id, anzahl in rezept[
            "zutaten"
        ].items():

            vorhanden = item_anzahl(
                item_id
            )

            if vorhanden >= anzahl:
                status = "OK"

            else:
                fehlt = (
                    anzahl - vorhanden
                )

                status = (
                    f"Fehlt: {fehlt}"
                )

            print(
                f"- {ITEMS[item_id]['name']} "
                f"x{anzahl} "
                f"(Du hast: {vorhanden}) "
                f"[{status}]"
            )

        print()

        if not rezept_kann_gekocht_werden(
            rezept
        ):
            print(
                "Dir fehlen Zutaten für "
                "dieses Rezept."
            )

            warte_auf_taste()
            continue

        zusatzportion = koch_zusatzportion(spieler, rezept_id)
        if koch_vorratskueche_gelernt(spieler):
            stand = koch_portionenstand(spieler)
            if zusatzportion:
                print("Vorratsküche: Diese Zubereitung ergibt eine zusätzliche Portion.")
            elif stand is not None:
                print(f"Vorratsküche: noch {4 - stand} erfolgreiche Zubereitungen bis zur Zusatzportion.")
            else:
                print("Der Portionenstand ist nicht lesbar; diese Zubereitung erhält keinen Bonus.")
        print(f"Ergebnis: {rezept.get('anzahl', 1) + zusatzportion}x {ITEMS[rezept['ergebnis']]['name']}")
        print()
        print("1. Zubereiten")
        print("2. Zurück")

        koch_auswahl = eingabe_menu(
            1,
            2,
            sonder_tasten=()
        )

        if koch_auswahl == 2:
            continue

        inventar_vorher = dict(spieler.get("inventar_items", {}))
        zutaten_entfernt = all(
            item_entfernen(item_id, anzahl)
            for item_id, anzahl in rezept["zutaten"].items()
        )
        if not zutaten_entfernt or not item_hinzufuegen(
            rezept["ergebnis"], rezept.get("anzahl", 1) + zusatzportion
        ):
            spieler["inventar_items"] = inventar_vorher
            print("Die Zubereitung konnte nicht abgeschlossen werden. Deine Zutaten bleiben erhalten.")
            warte_auf_taste("Zurück")
            continue

        koch_zubereitung_abschliessen(spieler, rezept_id)
        if zusatzportion:
            print("Vorratsküche: Eine zusätzliche Portion ist gelungen.")

        if koch_praxis_abschliessen(spieler, rezept_id):
            print(f"Kochpraxis festgehalten: {rezept['name']}.")
            if koch_praxis_fortschritt(spieler) == 2:
                print("Erstes Kochpraxisziel abgeschlossen: zwei unterschiedliche Gerichte.")

        print()

        design_text(
            f"{rezept['name']} zubereitet",
            design="positiv",
            art="menue"
        )

        warte_auf_taste()

def spielmenue():
    while True:
        ort_titel(
            "Menü"
        )

        print(
            "1. Weiterspielen"
        )

        print(
            "2. Textverlauf"
        )

        print(
            "3. Questlog/Erfolge"
        )

        print(
            "4. Spiel speichern"
        )

        print(
            "5. Optionen"
        )

        print(
            "6. Speichern & Hauptmenü"
        )

        menue_auswahl = eingabe_menu(
            1,
            6,
            sonder_tasten=()
        )

        if menue_auswahl == 1:
            return

        elif menue_auswahl == 2:
            textverlauf_anzeigen()

        elif menue_auswahl == 3:
            questlog()

        elif menue_auswahl == 4:
            spiel_speichern(
                spieler
            )

            warte_auf_taste()

        elif menue_auswahl == 5:
            optionen()

        elif menue_auswahl == 6:
            if spiel_speichern(
                spieler
            ):
                print()

                print(
                    "Du kehrst zum Hauptmenü zurück."
                )

                warte_auf_taste(
                    "Zum Hauptmenü"
                )

                zum_hauptmenue()
                return

            else:
                warte_auf_taste()

