def spielerhaus():
    ort_titel("Dein Haus")

    ort_nachricht_anzeigen()

    if spieler.get("prolog_status") in [
        "aufgewacht",
        "haus_erkundet"
    ]:
        prolog_haus()
        return

    menue_trenner()
    print()

    buecherregal_text = "1. Bücherregal anschauen"

    if (
        spieler.get(
            "quest_ein_name_fehlt"
        ) == "fahrtenbuch_untersuchen"
        and item_besitzt(
            "fahrtenbuch_haendler"
        )
    ):
        buecherregal_text += " [!]"

    elif (
        spieler.get(
            "quest_wiegenlied"
        ) == "abgeschlossen"
        and spieler.get(
            "quest_schmied"
        ) == "nicht_entdeckt"
    ):
        buecherregal_text += " [!]"

    print(buecherregal_text)
    print("2. Kochen")
    print("3. Inventar öffnen")
    print("4. Lager öffnen")
    print("5. Schlafen")
    print("6. Spiel speichern")
    print("7. Optionen")
    print("8. Speichern & Hauptmenü")
    print("9. Haus verlassen")

    print()
    print("[S] Status")
    print("[I] Inventar")
    print("[J] Questlog/Erfolge")
    print("[T] Talente")
    print("[Q] Speichern / Menü")

    haus_auswahl = eingabe_menu(
        1,
        9,
        sonder_tasten=("s", "i", "j", "t", "q")
    )

    if haus_auswahl == "s":
        status()
        return
    if haus_auswahl == "i":
        inventar()
        return
    if haus_auswahl == "j":
        questlog()
        return
    if haus_auswahl == "t":
        talentmenue()
        return
    if haus_auswahl == "q":
        spielmenue()
        return

    if haus_auswahl == 1:
        if prolog_laeuft():
            ort_titel("Dein Haus")

            text_ausgeben(
                "Du trittst vor das alte Bücherregal."
            )

            text_ausgeben(
                "Zwischen abgegriffenen Büchern stehen kleine Erinnerungsstücke und allerlei Krimskrams."
            )

            text_ausgeben(
                "Im Moment hast du allerdings wenig Lust, dich in eines der alten Bücher zu vertiefen."
            )

            warte_auf_taste()

        else:
            buecherregal()

    elif haus_auswahl == 2:
        kochen()

    elif haus_auswahl == 4:
        print("Noch nicht verfügbar")
        warte_auf_taste()

    elif haus_auswahl == 3:
        inventar()

    elif haus_auswahl == 5:
        if spieler["lebenspunkte"] < 100:
            print()
            print("Du legst dich in dein Bett und ruhst dich eine Weile aus.")
            print("Du fühlst dich wieder vollständig erholt.")

            spieler["lebenspunkte"] = 100

            print("Deine Lebenspunkte wurden vollständig wiederhergestellt.")
        else:
            print("Du fühlst dich bereits vollständig erholt.")
        warte_auf_taste()

    elif haus_auswahl == 6:
        spiel_speichern(spieler)
        warte_auf_taste()

    elif haus_auswahl == 7:
        optionen()

    elif haus_auswahl == 8:
        if spiel_speichern(spieler):
            print()
            print("Du kehrst zum Hauptmenü zurück.")

            warte_auf_taste("Zum Hauptmenü")

            zum_hauptmenue()
            return

        else:
            warte_auf_taste()

    elif haus_auswahl == 9:
        spieler["ort"] = "Eichenruh"

        ort_nachricht_setzen(
            "Du trittst hinaus.",
    )

def waffenwahl_bestaetigen(waffe, aktuelle_waffe=None, starter=False):
    ort_titel("Waffenauswahl - Vorschau")
    print(waffe["name"])
    print(f"Waffenart: {waffe.get('typ', 'Unbekannt')}")
    print()

    if aktuelle_waffe:
        print(f"Vergleich zu: {aktuelle_waffe['name']}")
        print("+ höher | - niedriger | = gleich")
        print()

    waffenvergleich_anzeigen(waffe, aktuelle_waffe)
    print()
    print("Möchtest du diese Waffe nehmen?" if starter
          else "Möchtest du diese Waffe ausrüsten?")
    print()
    print("1. Ja, nehmen" if starter else "1. Ja, ausrüsten")
    print("2. Nein, zurück zur Auswahl")

    return eingabe_menu(1, 2, sonder_tasten=()) == 1



