def waffenwert_holen(
    waffe,
    wert
):
    if not isinstance(
        waffe,
        dict
    ):
        return None

    if wert in waffe:
        return waffe.get(
            wert
        )

    # Kompatibilität mit bereits gespeicherten
    # Einfachen Speeren aus älteren Spielständen.
    if waffe.get(
        "name"
    ) == "Einfacher Speer":
        speer_standard = {
            "wendigkeit": 1,
            "parade": 1,
            "reichweite": 3
        }

        return speer_standard.get(
            wert
        )

    return None


def vergleichs_delta(
    neuer_wert,
    alter_wert
):
    if (
        isinstance(
            neuer_wert,
            bool
        )
        or isinstance(
            alter_wert,
            bool
        )
        or not isinstance(
            neuer_wert,
            (int, float)
        )
        or not isinstance(
            alter_wert,
            (int, float)
        )
    ):
        return "?"

    differenz = (
        neuer_wert
        - alter_wert
    )

    if differenz > 0:
        return (
            f"+{differenz:g}"
        )

    if differenz < 0:
        return (
            f"{differenz:g}"
        )

    return "="


def waffenvergleich_anzeigen(
    waffe,
    aktuelle_waffe=None
):
    min_schaden = (
        waffenwert_holen(
            waffe,
            "min_schaden"
        )
    )

    max_schaden = (
        waffenwert_holen(
            waffe,
            "max_schaden"
        )
    )

    if (
        isinstance(
            min_schaden,
            (int, float)
        )
        and not isinstance(
            min_schaden,
            bool
        )
        and isinstance(
            max_schaden,
            (int, float)
        )
        and not isinstance(
            max_schaden,
            bool
        )
    ):
        durchschnitt = (
            min_schaden
            + max_schaden
        ) / 2

        if aktuelle_waffe is not None:
            alt_min = (
                waffenwert_holen(
                    aktuelle_waffe,
                    "min_schaden"
                )
            )

            alt_max = (
                waffenwert_holen(
                    aktuelle_waffe,
                    "max_schaden"
                )
            )

            if (
                isinstance(
                    alt_min,
                    (int, float)
                )
                and isinstance(
                    alt_max,
                    (int, float)
                )
            ):
                alter_durchschnitt = (
                    alt_min
                    + alt_max
                ) / 2

                schaden_delta = (
                    vergleichs_delta(
                        durchschnitt,
                        alter_durchschnitt
                    )
                )

            else:
                schaden_delta = "?"

            print(
                f"   Schaden: "
                f"{min_schaden:g}-"
                f"{max_schaden:g} "
                f"(Ø {durchschnitt:g}, "
                f"{schaden_delta})"
            )

        else:
            print(
                f"   Schaden: "
                f"{min_schaden:g}-"
                f"{max_schaden:g} "
                f"(Ø {durchschnitt:g})"
            )

    else:
        print(
            "   Schaden: Unbekannt"
        )

    for name, wert_id in (
        (
            "Wendigkeit",
            "wendigkeit"
        ),
        (
            "Parade",
            "parade"
        ),
        (
            "Reichweite",
            "reichweite"
        )
    ):
        wert = waffenwert_holen(
            waffe,
            wert_id
        )

        if aktuelle_waffe is None:
            print(
                f"   {name}: "
                f"{wert if wert is not None else '?'}"
            )

            continue

        alter_wert = (
            waffenwert_holen(
                aktuelle_waffe,
                wert_id
            )
        )

        delta = vergleichs_delta(
            wert,
            alter_wert
        )

        print(
            f"   {name}: "
            f"{wert if wert is not None else '?'} "
            f"({delta})"
        )
    
def waffeninventar():
    while True:
        ort_titel("Inventar - Waffen")
        aktuelle_waffe = spieler.get("waffe")
        waffen = spieler["waffen_inventar"]

        if aktuelle_waffe:
            print(f"Ausgerüstet: {aktuelle_waffe['name']}")
            waffenvergleich_anzeigen(aktuelle_waffe)
        else:
            print("Ausgerüstet: Keine")

        if not waffen:
            print()
            print("Du hast keine weiteren Waffen.")
            warte_auf_taste()
            return

        print()
        if aktuelle_waffe:
            print("Vergleich zur ausgerüsteten Waffe:")
            print("+ höher | - niedriger | = gleich")
            print()

        for nummer, waffe in enumerate(waffen, start=1):
            print(f"{nummer}. {waffe['name']}")
            waffenvergleich_anzeigen(waffe, aktuelle_waffe)
            print()

        print(f"{len(waffen) + 1}. Zurück")
        auswahl = eingabe_menu(1, len(waffen) + 1, sonder_tasten=())
        if auswahl == len(waffen) + 1:
            return

        if not waffenwahl_bestaetigen(waffen[auswahl - 1], aktuelle_waffe):
            continue

        erfolgreich, neue_waffe, alte_waffe = (
            waffe_aus_inventar_ausruesten(auswahl - 1)
        )
        if not erfolgreich:
            return

        print()
        print(f"Du rüstest {neue_waffe['name']} aus.")
        if alte_waffe is not None:
            print(f"{alte_waffe['name']} wurde ins Inventar gelegt.")
        else:
            print("Du bist jetzt bewaffnet.")
        warte_auf_taste()
        return


def waffe_besitzt_name(
    waffen_name
):
    aktuelle_waffe = spieler.get(
        "waffe"
    )

    if (
        isinstance(
            aktuelle_waffe,
            dict
        )
        and aktuelle_waffe.get(
            "name"
        ) == waffen_name
    ):
        return True

    for waffe in spieler.get(
        "waffen_inventar",
        []
    ):
        if (
            isinstance(
                waffe,
                dict
            )
            and waffe.get(
                "name"
            ) == waffen_name
        ):
            return True

    return False

