def bjorn_revierwaffe_herstellen(waffen_id):
    daten = REVIERWAFFEN[waffen_id]
    waffen_name = daten["name"]
    werte = daten["werte"]
    kosten_gold = bjorn_arbeitskosten(daten["gold"])
    zutaten = daten["zutaten"]
    ort_titel(f"Bjorns Schmiede - {waffen_name}")
    print(
        f"Schaden: {werte['min_schaden']}-{werte['max_schaden']} | "
        f"Wendigkeit: {werte['wendigkeit']} | Parade: {werte['parade']} | "
        f"Reichweite: {werte['reichweite']}"
    )
    print(daten["beschreibung"])
    print()
    fehlende_zutaten = []
    for item_id, anzahl in zutaten.items():
        vorhanden = item_anzahl(item_id)
        print(f"Benötigt: {anzahl}x {ITEMS[item_id]['name']} "
              f"(Du hast: {vorhanden})")
        if vorhanden < anzahl:
            fehlende_zutaten.append((item_id, anzahl - vorhanden))
    print(f"Arbeitskosten: {kosten_gold} Gold")
    print(f"Gold vorhanden: {spieler['gold']}")
    if waffe_besitzt_name(waffen_name):
        design_text(f"Du besitzt bereits: {waffen_name}.",
                    design="warnung", art="menue")
        warte_auf_taste("Zurück")
        return
    fehlendes_gold = max(0, kosten_gold - spieler["gold"])
    if fehlende_zutaten or fehlendes_gold:
        design_text("Dir fehlen Materialien oder Gold.",
                    design="warnung", art="menue")
        for item_id, anzahl in fehlende_zutaten:
            print(f"Fehlt: {anzahl}x {ITEMS[item_id]['name']}")
        if fehlendes_gold:
            print(f"Fehlt: {fehlendes_gold} Gold")
        warte_auf_taste("Zurück")
        return
    menue_trenner()
    print()
    print(f"1. {waffen_name} herstellen lassen")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return
    entfernte_zutaten = {}
    for item_id, anzahl in zutaten.items():
        if not item_entfernen(item_id, anzahl):
            for alte_id, alte_anzahl in entfernte_zutaten.items():
                item_hinzufuegen(alte_id, alte_anzahl)
            design_text("Herstellung fehlgeschlagen.",
                        design="warnung", art="menue")
            warte_auf_taste("Zurück")
            return
        entfernte_zutaten[item_id] = anzahl
    spieler["gold"] -= kosten_gold
    neue_waffe = {"name": waffen_name}
    neue_waffe.update(werte)
    spieler.setdefault("waffen_inventar", []).append(neue_waffe)
    design_text(f"{waffen_name} hergestellt",
                design="positiv", art="menue")
    print("Die neue Waffe wurde in dein Waffeninventar gelegt.")
    print(f"Verbleibendes Gold: {spieler['gold']}")
    for item_id in zutaten:
        print(f"{ITEMS[item_id]['name']}: {item_anzahl(item_id)}")
    warte_auf_taste("Weiter")


def bjorn_jagdbeil_herstellen():
    waffen_name = "Verstärktes Jagdbeil"
    kosten_gold = bjorn_arbeitskosten(18)
    zutaten = {"keilerhauer": 2, "holz": 2}

    ort_titel("Bjorns Schmiede - Verstärktes Jagdbeil")
    print("Schaden: 10-18 | Wendigkeit: 1 | Parade: 1 | Reichweite: 1")
    print("Mehr Wucht als das Schwere Handbeil bei gleicher Handhabung.")
    print()
    print("Keilerhauer: Beute von Keilern auf der Wildspur.")
    print("Holz: Holzsuche im Wald.")
    print()

    fehlende_zutaten = []
    for item_id, anzahl in zutaten.items():
        vorhanden = item_anzahl(item_id)
        print(f"Benötigt: {anzahl}x {ITEMS[item_id]['name']} "
              f"(Du hast: {vorhanden})")
        if vorhanden < anzahl:
            fehlende_zutaten.append((item_id, anzahl - vorhanden))

    print(f"Arbeitskosten: {kosten_gold} Gold")
    print(f"Gold vorhanden: {spieler['gold']}")

    if waffe_besitzt_name(waffen_name):
        design_text("Du besitzt bereits ein Verstärktes Jagdbeil.",
                    design="warnung", art="menue")
        warte_auf_taste("Zurück")
        return

    fehlendes_gold = max(0, kosten_gold - spieler["gold"])
    if fehlende_zutaten or fehlendes_gold:
        design_text("Dir fehlen Materialien oder Gold.",
                    design="warnung", art="menue")
        for item_id, anzahl in fehlende_zutaten:
            print(f"Fehlt: {anzahl}x {ITEMS[item_id]['name']}")
        if fehlendes_gold:
            print(f"Fehlt: {fehlendes_gold} Gold")
        warte_auf_taste("Zurück")
        return

    menue_trenner()
    print()
    print("1. Verstärktes Jagdbeil herstellen lassen")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    entfernte_zutaten = {}
    for item_id, anzahl in zutaten.items():
        if not item_entfernen(item_id, anzahl):
            for alte_id, alte_anzahl in entfernte_zutaten.items():
                item_hinzufuegen(alte_id, alte_anzahl)
            design_text("Herstellung fehlgeschlagen.",
                        design="warnung", art="menue")
            warte_auf_taste("Zurück")
            return
        entfernte_zutaten[item_id] = anzahl

    spieler["gold"] -= kosten_gold
    spieler.setdefault("waffen_inventar", []).append({
        "name": waffen_name,
        "min_schaden": 10,
        "max_schaden": 18,
        "verkaufswert": 18,
        "typ": "Beil",
        "wendigkeit": 1,
        "parade": 1,
        "reichweite": 1
    })

    design_text("Verstärktes Jagdbeil hergestellt",
                design="positiv", art="menue")
    print("Die neue Waffe wurde in dein Waffeninventar gelegt.")
    print(f"Verbleibendes Gold: {spieler['gold']}")
    for item_id in zutaten:
        print(f"{ITEMS[item_id]['name']}: {item_anzahl(item_id)}")
    warte_auf_taste("Weiter")

