def bjorn_ausruestung_herstellen(gegenstand_id):
    rezepte = {
        "spurenleser_amulett": {
            "zutaten": {"keilerhauer": 1, "wolfsfell": 1},
            "gold": 15
        },
        "ring_der_standfestigkeit": {
            "zutaten": {"keilerhauer": 2},
            "gold": 20
        },
        "leichte_jaegerweste": {
            "zutaten": {"keilerhauer": 1, "wolfsfell": 2},
            "gold": 18
        },
        "schuppenweste": {
            "zutaten": {"glutschuppe": 3, "wolfsfell": 2},
            "gold": 20
        },
        "schieferweste": {
            "zutaten": {"schieferplatte": 3, "wolfsfell": 1},
            "gold": 25
        },
        "federamulett": {
            "zutaten": {"kreischerfeder": 3, "keilerhauer": 1},
            "gold": 15
        },
        "scherenarmschutz": {
            "zutaten": {"krebsschere": 2, "wolfsfell": 1},
            "gold": 18
        },
        "waldlaeuferweste": {
            "zutaten": {"graupelzfell": 1, "wolfsfell": 2},
            "gold": 30
        },
        "steinhautweste": {
            "zutaten": {"uraltschiefer": 1, "schieferplatte": 2, "wolfsfell": 1},
            "gold": 40
        },
        "geweihtalisman": {
            "zutaten": {"hirschgeweih": 2, "wolfsfell": 1},
            "gold": 20
        },
        "plattenweste": {
            "zutaten": {"kriecherplatte": 2, "molchhaut": 1},
            "gold": 30
        },
        "flatterhautbinde": {
            "zutaten": {"flatterhaut": 3},
            "gold": 15
        }
    }   

    rezept = rezepte.get(gegenstand_id)
    if rezept is None:
        return

    daten = AUSRUESTUNGS_GEGENSTAENDE[gegenstand_id]
    name = daten["name"]
    zutaten = rezept["zutaten"]
    kosten_gold = bjorn_arbeitskosten(rezept["gold"])

    ort_titel(f"Bjorns Schmiede - {name}")
    print(daten["beschreibung"])
    bjorn_satz = {
        "plattenweste": "[Bjorn] Leichter als Schiefer. Und wer da durchbeißen will, hat ein Problem.",
        "flatterhautbinde": "[Bjorn] Fühlt sich an wie nasses Leder. Hält aber."
    }.get(gegenstand_id)
    if bjorn_satz:
        print(bjorn_satz)
    print()
    if "keilerhauer" in zutaten:
        print("Keilerhauer: Beute von Keilern auf der Wildspur.")
    if "wolfsfell" in zutaten:
        print("Wolfsfell: Beute von Wölfen auf der Wildspur.")
    if "glutschuppe" in zutaten:
        print("Glutschuppe: Beute von Glutsalamandern in der Brandschneise.")
    if "schieferplatte" in zutaten:
        print("Schieferplatte: Beute von Schieferpanzern auf den Felsterrassen.")
    if "kreischerfeder" in zutaten:
        print("Kreischerfeder: Beute von Kreischern auf den Felsterrassen.")
    if "krebsschere" in zutaten:
        print("Krebsschere: Beute von Gezeitenkrebsen am Wrackstrand.")
    if "graupelzfell" in zutaten:
        print("Graupelzfell: Beute von Graupelz, dem seltenen alten Leitwolf der Wildspur.")
    if "hirschgeweih" in zutaten:
        print("Hirschgeweih: Beute von Echohirschen am Pfad des Vergessens.")
    if "uraltschiefer" in zutaten:
        print("Uraltschiefer: Beute vom Steinvater, dem seltenen Revierherrn der Felsterrassen.")
    if "kriecherplatte" in zutaten:
        print("Kriecherplatte: Beute von Schachtkriechern oder Fund in den Nebenstollen der TIEFEN.")
    if "molchhaut" in zutaten:
        print("Molchhaut: Beute von Blindmolchen oder Fund in den Nebenstollen der TIEFEN.")
    if "flatterhaut" in zutaten:
        print("Flatterhaut: Beute von Schachtflatterern oder Fund in den Nebenstollen der TIEFEN.")
    print("Materialien sind nicht bei jeder Jagd garantiert.")
    print()

    fehlende_zutaten = []
    for item_id, anzahl in zutaten.items():
        vorhanden = item_anzahl(item_id)
        print(f"Benötigt: {anzahl}x {ITEMS[item_id]['name']} "
              f"(Du hast: {vorhanden})")
        if vorhanden < anzahl:
            fehlende_zutaten.append((item_id, anzahl - vorhanden))

    print(f"Arbeitskosten: {kosten_gold} Gold")
    print(f"Gold vorhanden: {spieler['gold']}")

    if ausruestungsgegenstand_besitzt(gegenstand_id):
        design_text(f"Du besitzt bereits: {name}.",
                    design="warnung", art="menue")
        warte_auf_taste("Zurück")
        return

    fehlendes_gold = max(0, kosten_gold - spieler["gold"])
    if fehlende_zutaten or fehlendes_gold:
        design_text("Dir fehlen Materialien oder Gold.",
                    design="warnung", art="menue")
        for item_id, anzahl in fehlende_zutaten:
            print(f"Fehlt: {anzahl}x {ITEMS[item_id]['name']}")
        if fehlendes_gold:
            print(f"Fehlt: {fehlendes_gold} Gold")
        warte_auf_taste("Zurück")
        return

    menue_trenner()
    print()
    print(f"1. {name} herstellen lassen")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    entfernte_zutaten = {}
    for item_id, anzahl in zutaten.items():
        if not item_entfernen(item_id, anzahl):
            for alte_id, alte_anzahl in entfernte_zutaten.items():
                item_hinzufuegen(alte_id, alte_anzahl)
            design_text("Herstellung fehlgeschlagen.",
                        design="warnung", art="menue")
            warte_auf_taste("Zurück")
            return
        entfernte_zutaten[item_id] = anzahl

    if not ausruestungsgegenstand_hinzufuegen(gegenstand_id):
        for item_id, anzahl in entfernte_zutaten.items():
            item_hinzufuegen(item_id, anzahl)
        design_text("Herstellung fehlgeschlagen.",
                    design="warnung", art="menue")
        warte_auf_taste("Zurück")
        return

    spieler["gold"] -= kosten_gold
    design_text(f"{name} hergestellt", design="positiv", art="menue")
    print("Der Gegenstand wurde in dein Ausrüstungsinventar gelegt.")
    slot_name = "Rüstung" if daten["slot"] == "ruestung" else "Zubehör"
    print(f"Du kannst ihn unter Inventar > Ausrüstung > {slot_name} anlegen.")
    print(f"Verbleibendes Gold: {spieler['gold']}")
    warte_auf_taste("Weiter")


def bjorn_stahlkrieger():
    ort_titel("Bjorn – Stahlkrieger")
    if not stahlkrieger_voraussetzungen(spieler):
        print("Dieser Lehrweg ist für deinen aktuellen Ausbildungsstand nicht verfügbar.")
        warte_auf_taste("Zurück")
        return
    if hybrid_probe_offen(spieler, "stahlkrieger"):
        print("Beende zuerst deine andere anstehende Hybridprüfung. Während einer Probe kannst du den Hybrid nicht wechseln.")
        warte_auf_taste("Zurück")
        return
    text_ausgeben("[Bjorn] Du weißt, wie eine Waffe entsteht. Jetzt musst du lernen, ihrer Wucht standzuhalten und im richtigen Moment zurückzuschlagen.")
    print("Ambossstand [A]: Verteidigung mit bis zu 3 zusätzlicher Schadensminderung in dieser und der nächsten Runde.")
    print("Schmiedehieb [S]: Angriff 1 mit +50 % Waffenschaden, nur unmittelbar nach erfolgreicher Verteidigung.")
    print("Beide Fähigkeiten: vier Runden Einsatzabstand. Ein positiver Restschaden kann trotz Ambossstand bleiben.")
    print("Veredelte Waffenpflege: +4 statt +2 Schaden für die drei vorbereiteten Waffentreffer.")
    print("Deine Kriegerklasse und Deckung halten bleiben erhalten. Nur ein Hybrid ist aktiv.")
    if stahlkrieger_freigeschaltet(spieler):
        aktiv = hybrid_aktiv_holen(spieler) == "stahlkrieger"
        print("Prüfung abgeschlossen. Ein Hybridwechsel ist hier möglich.")
        print()
        print("1. Als reiner Krieger weiterspielen" if aktiv else "1. Zum Stahlkrieger fusionieren")
        print("2. Zurück")
        if eingabe_menu(1, 2, sonder_tasten=()) != 1:
            return
        ziel = None if aktiv else "stahlkrieger"
        print("Deine Grundklasse bleibt Krieger. Andere Freischaltungen bleiben erhalten; der Wechsel kostet nichts.")
        print()
        print("1. Ja, Hybridwahl bestätigen")
        print("2. Zurück")
        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            if hybrid_beim_lehrer_waehlen(spieler, ziel, "bjorn", bestaetigt=True):
                print("Hybrid aktiv: Stahlkrieger." if ziel else "Du spielst wieder als reiner Krieger.")
        warte_auf_taste("Zurück")
        return
    if spieler.get("hybrid", {}).get("stahlkrieger_probe", False):
        print("Prüfung bereit für den nächsten Kampf. Nutze deine vorbereitete Waffe.")
        print("Wehre mit Ambossstand erfolgreich einen tatsächlichen Angriff ab, triff mit Schmiedehieb und gewinne.")
        print(f"Aktuelle Lebenspunkte: {spieler['lebenspunkte']}/100")
        if spieler["lebenspunkte"] <= 35:
            print("Du bist schwer verletzt. Versorge dich vor der Prüfung.")
        warte_auf_taste("Zurück")
        return
    print("Prüfung: Ambossstand erfolgreich einsetzen, mit Schmiedehieb treffen und den nächsten Kampf gewinnen.")
    print("Die Prüfungsfähigkeiten ersetzen für diesen Kampf deinen bisherigen Hybrid; die Freischaltungen bleiben erhalten.")
    print("Heilung und Flucht sind erlaubt. Nach jedem Versuch endet die Probe; Gegenstände und Lebenspunkte werden regulär verbraucht.")
    print(f"Aktuelle Lebenspunkte: {spieler['lebenspunkte']}/100")
    if spieler["lebenspunkte"] <= 35:
        print("Du bist schwer verletzt. Versorge dich vor der Prüfung.")
    if not schmied_waffenpflege_kampfbonus(spieler, spieler.get("waffe")):
        print("Bereite zuerst deine ausgerüstete Waffe mit Waffenpflege vor. Ein Versuch kostet die regulären 2 Gold Vorbereitung.")
        warte_auf_taste("Zurück")
        return
    print()
    print("1. Stahlkrieger-Prüfung vorbereiten")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        if stahlkrieger_probe_starten(spieler, bestaetigt=True):
            print("Prüfung bereit. Verwende im nächsten Kampf diese Waffe; ein Waffenwechsel beendet den Versuch ohne Abschluss.")
    warte_auf_taste("Zurück")


def bjorn_waffenpflege():
    ort_titel("Bjorn – Waffenpflege")
    daten = spieler.get("berufe", {}).get("schmied", {}) if isinstance(spieler.get("berufe", {}), dict) else {}
    if (spieler.get("prolog_status") != "prolog_abgeschlossen"
            or not schmied_eigenbau_moeglich(spieler)
            or "hauermesser" not in daten.get("praxis", [])):
        text_ausgeben("[Bjorn] Stelle zuerst dein eigenes Hauermesser her. Dann zeige ich dir, wie du eine Waffe für ihren Einsatz vorbereitest.")
        warte_auf_taste("Zurück")
        return
    pflege_bonus = 4 if hybrid_aktiv_holen(spieler) == "stahlkrieger" else 2
    print(f"Waffenpflege: +{pflege_bonus} Schaden bei den ersten drei erfolgreichen Waffenangriffen im nächsten Kampf.")
    if pflege_bonus == 4:
        print("Veredelte Waffenpflege wirkt nur, solange du im Kampf als Stahlkrieger antrittst.")
    print("Verfehlen und Zauber verbrauchen keine Anwendung. Abwehrschaden erhält keinen Bonus.")
    print("Die Vorbereitung gilt für diese Waffe und verfällt mit dem nächsten Kampfende, auch bei Flucht.")
    if not schmied_waffenpflege_gelernt(spieler):
        text_ausgeben("[Bjorn] Eine gute Schneide ist kein Zufall. Ich zeige dir, worauf du vor einem Kampf achten musst.")
        print("Die Technik zu lernen ist kostenlos. Jede spätere Vorbereitung kostet 2 Gold.")
        print()
        print("1. Waffenpflege lernen")
        print("2. Zurück")
        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            if schmied_waffenpflege_lernen(spieler, bestaetigt=True):
                print("Schmiedetechnik gelernt: Waffenpflege.")
            else:
                print("Die Technik kann mit deinem aktuellen Berufsstand nicht gelernt werden.")
        warte_auf_taste("Zurück")
        return
    bereit = schmied_waffenpflege_bereit(spieler)
    if bereit is not None:
        print(f"Bereits vorbereitet: {bereit}. Eine weitere Vorbereitung ist erst nach dem nächsten Kampf möglich.")
        print("Verwendest du im nächsten Kampf eine andere Waffe, verfällt die Vorbereitung ohne Bonus.")
        warte_auf_taste("Zurück")
        return
    waffe = spieler.get("waffe")
    if not isinstance(waffe, dict):
        print("Rüste zuerst eine Waffe aus.")
        warte_auf_taste("Zurück")
        return
    print(f"Ausgerüstete Waffe: {waffe.get('name', 'Unbekannt')}")
    print(f"Kosten: 2 Gold | Vorhanden: {spieler.get('gold', 0)} Gold")
    print("Materialkunde verändert diese Vorbereitungskosten nicht.")
    print()
    print("1. Ausgerüstete Waffe vorbereiten")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        if schmied_waffenpflege_vorbereiten(spieler, bestaetigt=True):
            print("Deine Waffe ist für den nächsten Kampf vorbereitet.")
        else:
            print("Vorbereitung nicht möglich. Prüfe Gold, Waffe und Berufsstand.")
    warte_auf_taste("Zurück")


def bjorn_eigene_herstellung():
    ort_titel("Bjorns Werkbank – eigene Herstellung")
    if spieler.get("prolog_status") != "prolog_abgeschlossen":
        print("Die Werkbank steht dir nach dem Prolog zur Verfügung.")
        warte_auf_taste("Zurück")
        return
    if not schmied_eigenbau_moeglich(spieler):
        text_ausgeben("[Bjorn] Schließe zuerst die Schmiedeausbildung ab. Dann kannst du hier selbst arbeiten.")
        warte_auf_taste("Zurück")
        return
    while spieler.get("spiel_laeuft", True):
        ort_titel("Bjorns Werkbank – eigene Herstellung")
        text_ausgeben(
            "[Bjorn] Du führst die Arbeit selbst aus. Für Verbrauchsmittel "
            "und Werkzeugpflege fallen nur die Werkstattkosten an."
        )
        kosten = bjorn_arbeitskosten(4)
        print(f"Hauermesser: 2x Keilerhauer + {kosten} Gold Werkstattkosten")
        print("Schaden: 10–14 | Parade: 2 | Wendigkeit: 3 | Reichweite: 1")
        print("Deine Berufspraxis wird beim ersten erfolgreichen Eigenbau festgehalten.")
        print()
        print("1. Hauermesser selbst herstellen")
        print("2. Waffenpflege bei Bjorn")
        hybrid_angebot = stahlkrieger_voraussetzungen(spieler)
        if hybrid_angebot:
            print("3. Bjorns weiterführenden Krieger-Schmied-Lehrweg ansehen")
        zurueck = 4 if hybrid_angebot else 3
        print(f"{zurueck}. Zurück")
        auswahl = eingabe_menu(1, zurueck, sonder_tasten=())
        if auswahl == zurueck:
            return
        if auswahl == 2:
            bjorn_waffenpflege()
        elif auswahl == 3 and hybrid_angebot:
            bjorn_stahlkrieger()
        else:
            bjorn_hauermesser_herstellen(selbst=True)


def bjorn_hauermesser_herstellen(*, selbst=False):
    if type(selbst) is not bool:
        return
    if selbst and (
        spieler.get("prolog_status") != "prolog_abgeschlossen"
        or not schmied_eigenbau_moeglich(spieler)
        or not isinstance(spieler.get("waffen_inventar", []), list)
    ):
        print("Diese eigene Herstellung steht dir momentan nicht zur Verfügung.")
        warte_auf_taste("Zurück")
        return
    kosten_hauer = 2
    kosten_gold = bjorn_arbeitskosten(4 if selbst else 12)
    waffen_name = "Hauermesser"

    ort_titel(
        "Bjorns Schmiede - Hauermesser"
    )

    text_ausgeben(
        "Bjorn nimmt einen Keilerhauer in die Hand "
        "und prüft seine Krümmung."
    )

    print()

    text_ausgeben(
        "[Bjorn] Für eine lange Klinge taugt das nicht. "
        "Aber für ein kurzes Messer kann man damit arbeiten."
    )

    print()

    print(
        f"Benötigt: {kosten_hauer}x Keilerhauer"
    )

    print(
        f"{'Werkstattkosten' if selbst else 'Arbeitskosten'}: {kosten_gold} Gold"
    )

    print(
        f"Du besitzt: "
        f"{item_anzahl('keilerhauer')}x Keilerhauer"
    )

    print(
        f"Gold vorhanden: "
        f"{spieler['gold']}"
    )

    if waffe_besitzt_name(
        waffen_name
    ):
        print()

        design_text(
            "Du besitzt bereits ein Hauermesser.",
            design="warnung",
            art="menue"
        )

        warte_auf_taste(
            "Zurück"
        )

        return

    fehlende_hauer = max(
        0,
        kosten_hauer
        - item_anzahl(
            "keilerhauer"
        )
    )

    fehlendes_gold = max(
        0,
        kosten_gold
        - spieler[
            "gold"
        ]
    )

    if (
        fehlende_hauer > 0
        or fehlendes_gold > 0
    ):
        print()

        design_text(
            "Dir fehlen Materialien oder Gold.",
            design="warnung",
            art="menue"
        )

        if fehlende_hauer > 0:
            print(
                f"Fehlt: "
                f"{fehlende_hauer}x Keilerhauer"
            )

        if fehlendes_gold > 0:
            print(
                f"Fehlt: "
                f"{fehlendes_gold} Gold"
            )

        warte_auf_taste(
            "Zurück"
        )

        return

    menue_trenner()

    if selbst:
        print()
    print(
        "1. Hauermesser selbst herstellen" if selbst
        else "1. Hauermesser herstellen lassen"
    )

    print(
        "2. Zurück"
    )

    auswahl = eingabe_menu(
        1,
        2,
        sonder_tasten=()
    )

    if auswahl == 2:
        return

    if not item_entfernen(
        "keilerhauer",
        kosten_hauer
    ):
        return

    spieler[
        "gold"
    ] -= kosten_gold

    spieler.setdefault(
        "waffen_inventar",
        []
    ).append({
        "name": waffen_name,
        "min_schaden": 10,
        "max_schaden": 14,
        "verkaufswert": 12,
        "typ": "Messer",
        "wendigkeit": 3,
        "parade": 2,
        "reichweite": 1
    })

    if selbst and schmied_praxis_abschliessen(spieler, "hauermesser"):
        print("Schmiedepraxis abgeschlossen: erstes eigenes Hauermesser.")

    print()

    design_text(
        "Hauermesser hergestellt",
        design="positiv",
        art="menue"
    )

    print()

    print(
        "Die neue Waffe wurde in dein "
        "Waffeninventar gelegt."
    )

    print(
        f"Verbleibendes Gold: "
        f"{spieler['gold']}"
    )

    print(
        f"Keilerhauer: "
        f"{item_anzahl('keilerhauer')}"
    )

    warte_auf_taste(
        "Weiter"
    )

