def ausruestung_kennwert(slot, schluessel):
    # Kennwerte stehen in den Ausrüstungsdaten; so zählt jede Wirkung genau einmal.
    gegenstand = ausruestung_holen(slot)

    if not isinstance(gegenstand, dict):
        return 0

    daten = AUSRUESTUNGS_GEGENSTAENDE.get(gegenstand.get("id"), {})
    wert = daten.get(schluessel, 0)

    return wert if type(wert) is int else 0


def krankenstube_ohne_ida(text):
    # Wundsalbe gibt es auch ohne Ida (Quest nicht begonnen oder Ida fort).
    while True:
        ort_titel("Universität von Oros - Krankenstube")
        text_ausgeben(text, art="menue")
        menue_trenner()
        print()
        print("1. Wundsalbe kaufen")
        print("2. Gegengift kaufen")
        print("3. Zurück zur zentralen Halle")
        print()
        print("[S] Status")
        print("[I] Inventar")
        print("[J] Questlog/Erfolge")
        print("[T] Talente")
        print("[Q] Speichern / Menü")

        auswahl = eingabe_menu(
            1,
            3,
            sonder_tasten=("s", "i", "j", "t", "q")
        )

        if auswahl == "s":
            status()
            return
        if auswahl == "i":
            inventar()
            return
        if auswahl == "j":
            questlog()
            return
        if auswahl == "t":
            talentmenue()
            return
        if auswahl == "q":
            spielmenue()
            return
        if auswahl == 3:
            return
        if auswahl == 2:
            krankenstube_gegengift(
                "[Helferin] Gegengift hilft gegen Bisse. Am besten trinkst du "
                "es, wenn der Kampf vorbei ist."
            )
            continue

        krankenstube_wundsalbe(
            "[Helferin] Wundsalbe gegen Blutungen. Mehr als drei braucht "
            "niemand auf einmal."
        )


def haendler_kaufen(
    titel,
    begruessung,
    sortiment,
    obergrenzen=None
):
    while True:
        ort_titel(titel)

        print(
            begruessung
        )

        print()

        print(
            f"Gold vorhanden: {spieler['gold']}"
        )

        print()

        waren = list(
            sortiment.items()
        )

        for nummer, (
            item_id,
            handels_daten
        ) in enumerate(
            waren,
            start=1
        ):
            print(
                f"{nummer}. "
                f"{ITEMS[item_id]['name']} "
                f"- {handels_daten['preis']} Gold "
                f"(Du hast: {item_anzahl(item_id)})"
            )

        zurueck_nummer = (
            len(waren) + 1
        )

        print()
        print(
            f"{zurueck_nummer}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        item_id, handels_daten = (
            waren[
                auswahl - 1
            ]
        )

        preis = handels_daten[
            "preis"
        ]

        max_anzahl = (
            spieler["gold"] // preis
        )

        grenze = (obergrenzen or {}).get(item_id)

        if grenze is not None and item_anzahl(item_id) >= grenze:
            print()
            print(
                f"Du kannst höchstens {grenze} tragen."
            )

            warte_auf_taste()
            continue

        if grenze is not None:
            max_anzahl = min(
                max_anzahl,
                grenze - item_anzahl(item_id)
            )

        if max_anzahl <= 0:
            print()
            print(
                "Du hast nicht genug Gold."
            )

            warte_auf_taste()
            continue

        ort_titel(
            f"{ITEMS[item_id]['name']} kaufen"
        )

        print(
            f"Preis: {preis} Gold pro Stück"
        )

        print(
            f"Gold vorhanden: {spieler['gold']}"
        )

        print(
            f"Du kannst maximal "
            f"{max_anzahl} kaufen."
        )

        print()
        print("0. Zurück")

        anzahl = eingabe_zahl(
            0,
            max_anzahl
        )

        if anzahl == 0:
            continue

        gesamtkosten = (
            anzahl * preis
        )

        if not handel_bestaetigen(ITEMS[item_id]["name"], anzahl, preis):
            continue

        spieler[
            "gold"
        ] -= gesamtkosten

        item_hinzufuegen(
            item_id,
            anzahl
        )

        print()

        design_text(
            (
                f"{anzahl}x "
                f"{ITEMS[item_id]['name']} erhalten"
            ),
            design="positiv",
            art="menue"
        )

        print(
            f"Bezahlt: "
            f"{gesamtkosten} Gold"
        )

        print(
            f"Verbleibendes Gold: "
            f"{spieler['gold']}"
        )

        print(
            f"{ITEMS[item_id]['name']}: "
            f"{item_anzahl(item_id)}"
        )

        warte_auf_taste()

def materialien_verkaufen(
    titel,
    begruessung,
    ankauf
):
    while True:
        ort_titel(
            titel
        )

        print(
            begruessung
        )

        print()

        print(
            f"Gold vorhanden: "
            f"{spieler['gold']}"
        )

        print()

        verkaufbare_items = []

        for item_id, handels_daten in ankauf.items():
            anzahl = item_anzahl(
                item_id
            )

            if anzahl <= 0:
                continue

            verkaufbare_items.append(
                (
                    item_id,
                    handels_daten,
                    anzahl
                )
            )

        if not verkaufbare_items:
            print(
                "Du hast momentan keine Materialien, "
                "die hier angekauft werden."
            )

            warte_auf_taste(
                "Zurück"
            )

            return

        for nummer, (
            item_id,
            handels_daten,
            anzahl
        ) in enumerate(
            verkaufbare_items,
            start=1
        ):
            print(
                f"{nummer}. "
                f"{ITEMS[item_id]['name']} "
                f"- {handels_daten['preis']} Gold "
                f"(Du hast: {anzahl})"
            )

        zurueck_nummer = (
            len(
                verkaufbare_items
            ) + 1
        )

        print()

        print(
            f"{zurueck_nummer}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        (
            item_id,
            handels_daten,
            vorhanden
        ) = verkaufbare_items[
            auswahl - 1
        ]

        preis = handels_daten[
            "preis"
        ]

        ort_titel(
            f"{ITEMS[item_id]['name']} verkaufen"
        )

        print(
            f"Ankaufspreis: "
            f"{preis} Gold pro Stück"
        )

        print(
            f"Du besitzt: "
            f"{vorhanden}"
        )

        print()

        print(
            "0. Zurück"
        )

        anzahl = eingabe_zahl(
            0,
            vorhanden
        )

        if anzahl == 0:
            continue

        if not handel_bestaetigen(ITEMS[item_id]["name"], anzahl, preis, verkauf=True):
            continue

        if not item_entfernen(
            item_id,
            anzahl
        ):
            print()

            design_text(
                "Verkauf fehlgeschlagen.",
                design="warnung",
                art="menue"
            )

            warte_auf_taste(
                "Weiter"
            )

            continue

        erloes = (
            anzahl
            * preis
        )

        spieler[
            "gold"
        ] += erloes

        print()

        design_text(
            (
                f"{anzahl}x "
                f"{ITEMS[item_id]['name']} verkauft"
            ),
            design="positiv",
            art="menue"
        )

        print()

        print(
            f"Du erhältst "
            f"{erloes} Gold."
        )

        print(
            f"Gold: "
            f"{spieler['gold']}"
        )

        warte_auf_taste(
            "Weiter"
        )

