def alte_schmiede_symbolraetsel():
    symbole = [
        "Amboss",
        "Wasser",
        "Flamme"
    ]

    reihenfolge = []

    wissen_hinweis = untersuchung_pruefung(
        "wissen",
        2
    )

    for position in range(
        1,
        4
    ):
        ort_titel(
            "Alte Schmiede - Werkbank"
        )

        text_ausgeben(
            "Die drei Metallplatten sitzen bündig in der Front der alten Schublade.",
            art="menue"
        )

        text_ausgeben(
            "Auf den drei Metallplatten sind ein Amboss, eine Wellenlinie für Wasser "
            "und eine Flamme zu erkennen. Jede Platte lässt sich ein Stück eindrücken.",
            art="menue"
        )

        if (
            position == 1
            and wissen_hinweis
        ):
            print()

            design_text(
                "Du denkst an die drei Sätze an den Arbeitsplätzen der Schmiede.",
                design="wissen",
                art="menue"
            )

            design_text(
                "Die Symbole könnten für die Arbeitsschritte stehen, "
                "mit denen ein Schmied ein Werkstück herstellt.",
                design="wissen",
                art="menue"
            )

        if reihenfolge:
            print()

            design_text(
                "Bisher: "
                + " → ".join(
                    reihenfolge
                ),
                design="wissen",
                art="menue"
            )

        menue_trenner()

        print(
            f"Position {position} von 3"
        )

        print()

        for nummer, symbol in enumerate(
            symbole,
            start=1
        ):
            print(
                f"{nummer}. {symbol}"
            )

        abbrechen_nummer = (
            len(symbole) + 1
        )

        print(
            f"{abbrechen_nummer}. Abbrechen"
        )

        auswahl = eingabe_menu(
            1,
            abbrechen_nummer,
            sonder_tasten=()
        )

        if (
            auswahl
            == abbrechen_nummer
        ):
            return False

        symbol = symbole.pop(
            auswahl - 1
        )

        reihenfolge.append(
            symbol
        )

    ort_titel(
        "Alte Schmiede - Werkbank"
    )

    design_text(
        " → ".join(
            reihenfolge
        ),
        design="wissen",
        art="menue"
    )

    print()

    if reihenfolge == [
        "Flamme",
        "Amboss",
        "Wasser"
    ]:
        text_ausgeben(
            "Die letzte Metallplatte bleibt gedrückt. Einen Augenblick später "
            "rastet auch im Inneren der Werkbank etwas ein."
        )

        text_ausgeben(
            "Ein verrosteter Riegel gleitet mit einem rauen Schaben zurück."
        )

        print()

        text_ausgeben(
            "Die feststeckende Schublade springt einen Fingerbreit auf."
        )

        print()

        text_ausgeben(
            "Zwischen rostigen Nägeln und altem Werkzeug "
            "liegt ein gefaltetes Stück Papier."
        )

        text_ausgeben(
            "Die Schrift darauf ist fast verblasst."
        )

        print()

        text_ausgeben(
            '"Was bleiben soll, ruht dort, '
            'wo selbst das Feuer stirbt."'
        )

        akt1_lernerfahrung(
            "alte_schmiede"
        )

        spieler[
            "quest_schmied"
        ] = "neuer_hinweis"

        quest_meldung(
            "update",
            "Der Schmied des Weges",
            "Deute den Hinweis in der alten Schmiede."
        )

        warte_auf_taste(
            "Weiter"
        )

        return True

    text_ausgeben(
        "Für einen Moment hörst du etwas "
        "im Inneren der Werkbank klicken."
    )

    print()

    text_ausgeben(
        "Dann springen alle drei Metallplatten "
        "wieder in ihre Ausgangsposition zurück."
    )

    text_ausgeben(
        "Die Reihenfolge war offenbar falsch."
    )

    warte_auf_taste(
        "Noch einmal überlegen"
    )

    return False

