def oros_tiefen_hinweise_verknuepfen():
    verbindungen = spieler.setdefault(
        "oros_tiefen_verknuepfungen",
        []
    )

    hinweise = [
        (
            "ignaz",
            "Ignaz: Unter TIEFEN fehlt ein gewöhnlicher "
            "Abschluss- oder Verlegungsvermerk."
        ),
        (
            "valerie",
            "Valerie: Die Mauer vor dem alten Zugang "
            "gehört nicht zum ursprünglichen Kernbau."
        ),
        (
            "finch",
            "Finch: Alte Umbauakten können unter Bauabschnitt, "
            "Kostenstelle oder Lehrstuhl abgelegt worden sein."
        ),
        (
            "hohlraum",
            "Eigene Untersuchung: Hinter der Mauer "
            "befindet sich zumindest teilweise ein Hohlraum."
        )
    ]

    while True:
        ort_titel(
            "Was Oros vergessen hat - Hinweise"
        )

        text_ausgeben(
            "Du gehst die bisherigen Erkenntnisse "
            "über die TIEFEN noch einmal durch.",
            art="menue"
        )

        print()

        text_ausgeben(
            "Vielleicht ergibt sich etwas Neues, "
            "wenn du zwei davon direkt miteinander vergleichst.",
            art="menue"
        )

        menue_trenner()
        print()

        for nummer, (_, text) in enumerate(
            hinweise,
            start=1
        ):
            print(
                f"{nummer}. {text}"
            )

        zurueck_option = len(
            hinweise
        ) + 1

        print(
            f"{zurueck_option}. Zurück"
        )

        erste_auswahl = eingabe_menu(
            1,
            zurueck_option,
            sonder_tasten=()
        )

        if erste_auswahl == zurueck_option:
            return

        erster_id, erster_text = hinweise[
            erste_auswahl - 1
        ]

        ort_titel(
            "Was Oros vergessen hat - Verbindung"
        )

        design_text(
            "ERSTER HINWEIS",
            design="wissen",
            art="menue"
        )

        print(
            erster_text
        )

        print()

        print(
            "Womit möchtest du diesen Hinweis verbinden?"
        )

        menue_trenner()
        print()

        zweite_hinweise = [
            hinweis
            for hinweis in hinweise
            if hinweis[0] != erster_id
        ]

        for nummer, (_, text) in enumerate(
            zweite_hinweise,
            start=1
        ):
            print(
                f"{nummer}. {text}"
            )

        zurueck_option = len(
            zweite_hinweise
        ) + 1

        print(
            f"{zurueck_option}. Andere Hinweise wählen"
        )

        zweite_auswahl = eingabe_menu(
            1,
            zurueck_option,
            sonder_tasten=()
        )

        if zweite_auswahl == zurueck_option:
            continue

        zweiter_id, zweiter_text = zweite_hinweise[
            zweite_auswahl - 1
        ]

        verbindung = frozenset(
            (
                erster_id,
                zweiter_id
            )
        )

        print()

        # -------------------------
