def oros_tiefen_zugang_untersuchen():
    ort_titel(
        "Universität von Oros - Alter TIEFEN-Zugang"
    )

    if schutz_quest_status() == "mauer":
        schutz_mauer_oeffnen()
        return

    if schutz_quest_status() == "abgeschlossen":
        tiefen_zugang()
