def levin_lieferung_abgleichen():
    ort_titel("Universität von Oros - Lieferverzeichnis")
    if spieler.get("oros_listen_voraufgabe") is True:
        text_ausgeben("[Levin] Diese Lieferung haben wir schon abgeglichen.")
        text_ausgeben("[Levin] Zwölf Tücher bestellt, zwölf angekommen.")
        warte_auf_taste("Weiter")
        return

    text_ausgeben(
        "[Levin] Könntest du diese beiden Einträge vergleichen? "
        "Dann kann ich die anderen Belege heraussuchen."
    )
    print()
    print("1. Ja, ich helfe dir.")
    print("2. Vielleicht später.")
    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    while True:
        ort_titel("Universität von Oros - Zwei Einträge")
        text_ausgeben("Levin legt zwei Blätter nebeneinander.")
        print()
        print("Frachtblatt: Zwei Kisten mit je sechs Leinentüchern.")
        print("Empfang der Krankenstube: Zwölf Leinentücher.")
        print()
        print("1. Es fehlen zehn Tücher.")
        print("2. Die Mengen stimmen überein.")
        print("3. Ich möchte später weitermachen.")
        auswahl = eingabe_menu(1, 3, sonder_tasten=())
        if auswahl == 3:
            return
        if auswahl == 1:
            text_ausgeben(
                "[Levin] Auf dem Frachtblatt steht zuerst die Zahl "
                "der Kisten. Was steht dahinter?"
            )
            warte_auf_taste("Noch einmal ansehen")
            continue

        spieler["oros_listen_voraufgabe"] = True
        text_ausgeben("[Levin] Ja. Dann kann ich den Eintrag abhaken.")
        text_ausgeben("Er setzt ein kleines Zeichen neben die Lieferung.")
        text_ausgeben(
            "[Levin] Danke. Wenn du Ida siehst: "
            "Die zwölf Tücher sind auch im Verzeichnis bestätigt."
        )
        warte_auf_taste("Weiter")
        return

def oros_lieferung17_lesen(quelle):
    if quelle not in ("ida", "levin"):
        return
    if spieler.get("oros_listen_voraufgabe") is not True:
        return

    status = spieler.get("quest_oros_listen", "nicht_entdeckt")
    if status not in (
        "nicht_entdeckt", "lieferung_pruefen", "belege_vergleichen",
        "entscheidung_offen", "abgeschlossen"
    ):
        return
    if status == "nicht_entdeckt":
        if quelle == "levin":
            text_ausgeben("[Levin] Frag Ida, welche Lieferung sie prüfen lassen möchte.")
            warte_auf_taste("Weiter")
            return
        text_ausgeben(
            "[Ida] Bei Lieferung 17 fehlt uns Leinen. "
            "Acht Ballen habe ich angenommen. Bezahlt sein sollen zwölf."
        )
        text_ausgeben("[Ida] Kannst du nachsehen, was in den Unterlagen steht?")
        print()
        print("1. Ja, ich prüfe die Lieferung.")
        print("2. Vielleicht später.")
        if eingabe_menu(1, 2, sonder_tasten=()) == 2:
            return
        spieler["quest_oros_listen"] = "lieferung_pruefen"
        quest_meldung(
            "neu", "Ein Name auf der Liste",
            "Prüfe Lieferung 17 mit Levin im Archiv."
        )

    ort_titel("Universität von Oros - Lieferung 17")
    if quelle == "ida":
        text_ausgeben("Ida legt ihre Empfangsnotiz vor dich.")
        print("Lieferung 17: Acht Ballen Leinen in der Krankenstube empfangen.")
        text_ausgeben("[Ida] Die Menge habe ich beim Abladen selbst geprüft.")
        beleg_id = "krankenstube"
    else:
        text_ausgeben("Levin schlägt das Bestell- und Zahlungsverzeichnis auf.")
        print("Lieferung 17: Zwölf Ballen Leinen für die Krankenstube. Bezahlt.")
        text_ausgeben(
            "[Levin] Zwölf Ballen. "
            "Das ist eine andere Lieferung als die zwölf Tücher von vorhin."
        )
        beleg_id = "bestellung"

    belege = spieler.get("oros_listen_belege")
    if not isinstance(belege, dict):
        belege = {}
        spieler["oros_listen_belege"] = belege
    belege[beleg_id] = True
    warte_auf_taste("Weiter")

def oros_listen_belege_vergleichen():
    if spieler.get("quest_oros_listen") not in (
        "lieferung_pruefen", "belege_vergleichen", "entscheidung_offen"
    ):
        return

    belege = spieler.get("oros_listen_belege", {})
    benoetigt = ("bestellung", "krankenstube", "frachtbrief", "verkauf")
    if not isinstance(belege, dict) or not all(
        belege.get(beleg_id) is True for beleg_id in benoetigt
    ):
        text_ausgeben("Für den Vergleich fehlen dir noch geprüfte Belege.")
        warte_auf_taste("Weiter")
        return

    if spieler.get("oros_listen_vergleich") is True:
        text_ausgeben(
            "Die vier Belege zeigen: Raban verkaufte vier Ballen privat, "
            "obwohl sie für die Krankenstube bezahlt waren."
        )
        warte_auf_taste("Weiter")
        return

    while True:
        ort_titel("Universität von Oros - Belege vergleichen")
        print("Bestellung: Zwölf Ballen für die Krankenstube bezahlt.")
        print("Empfangsnotiz: Acht Ballen in der Krankenstube angekommen.")
        print("Frachtbrief: Zwölf Ballen geliefert und von Raban angenommen.")
        print("Kaufbeleg: Vier Ballen aus Lieferung 17 privat von Raban verkauft.")
        print()
        print("1. Der Fuhrmann hat vier Ballen nicht geliefert.")
        print("2. Die anderen vier Ballen waren für einen anderen Empfänger bestellt.")
        print("3. Raban hat vier für die Krankenstube bezahlte Ballen privat verkauft.")
        print("4. Ich möchte die Unterlagen später vergleichen.")
        auswahl = eingabe_menu(1, 4, sonder_tasten=())
        if auswahl == 4:
            return
        if auswahl == 1:
            text_ausgeben("Der Frachtbrief bestätigt die vollständige Anlieferung.")
        elif auswahl == 2:
            text_ausgeben("Die Bestellung nennt die Krankenstube als Empfänger aller zwölf Ballen.")
        else:
            spieler["oros_listen_vergleich"] = True
            spieler["quest_oros_listen"] = "belege_vergleichen"
            text_ausgeben(
                "Liefernummer, Mengen und Unterschriften passen zusammen. "
                "Die fehlenden vier Ballen gingen an den Händler."
            )
            quest_meldung(
                "update", "Ein Name auf der Liste",
                "Sprich mit Raban über den privaten Verkauf."
            )
            warte_auf_taste("Weiter")
            return
        warte_auf_taste("Noch einmal ansehen")

def raban_angebot_anhoeren():
    bisher = oros_listen_entscheidung_holen()
    if bisher is not None:
        text_ausgeben(
            "Raban wendet sich ab. Seit du die Belege vorgelegt hast, hat er dir nichts mehr anzubieten."
            if bisher == "beweise_vorgelegt"
            else (
                "[Raban] Die Weste und das Vorratspaket hast du erhalten. Unsere Abmachung ist erfüllt."
                if spieler.get("oros_listen_lagerpaket_erhalten") is True
                else "[Raban] Die Weste hast du. Dein zugesagtes Vorratspaket kannst du im Lager abholen. Danach ist unsere Abmachung erfüllt."
            )
        )
        warte_auf_taste("Weiter")
        return

    belege = spieler.get("oros_listen_belege", {})
    if (
        spieler.get("quest_oros_listen") not in ("belege_vergleichen", "entscheidung_offen")
        or spieler.get("oros_listen_vergleich") is not True
        or not isinstance(belege, dict)
        or not all(belege.get(key) is True for key in (
            "bestellung", "krankenstube", "frachtbrief", "verkauf"
        ))
    ):
        text_ausgeben("Vergleiche zuerst die vier Belege, bevor du Raban damit konfrontierst.")
        warte_auf_taste("Weiter")
        return

    ort_titel("Universität von Oros - Rabans Angebot")
    if spieler.get("oros_listen_angebot_gezeigt") is not True:
        text_ausgeben(
            f'[{spieler["name"]}] Die zwölf Ballen waren für die Krankenstube bezahlt. '
            "Ida hat acht bekommen. Der Händler hat dir die anderen vier bezahlt."
        )
        text_ausgeben(
            "[Raban] Und morgen braucht sie vielleicht sechs. "
            "Lagerhaltung funktioniert nicht nach Wunschlisten."
        )
        text_ausgeben(f'[{spieler["name"]}] Das Geld ging an dich.')
        text_ausgeben(
            "Raban legt den Frachtbrief beiseite. "
            "Aus einer Schublade nimmt er ein vorbereitetes Blatt."
        )
        text_ausgeben("[Raban] Du warst im Archiv. Deine Aussage hätte Gewicht.")

    print()
    print('Aussage: "Ich habe gesehen, wie Levin die Unterlagen zu Lieferung 17 verändert hat."')
    text_ausgeben(
        "Du hast das nicht beobachtet. "
        "Die geprüften Belege stützen diese Behauptung nicht."
    )
    text_ausgeben(
        "[Raban] Für deine Unterschrift bekommst du eine Verstärkte Reiseweste "
        "und Zugang zu meinem Lager."
    )
    text_ausgeben("[Raban] Levin könnte dadurch seine Stelle und seinen Aufenthalt hier verlieren.")
    print("Angebot: Reiseweste mit Schutz 4; Lagerzugang mit einmalig zwei Bandagen und einem Heiltrank.")

    erstmals = spieler.get("oros_listen_angebot_gezeigt") is not True
    spieler["oros_listen_angebot_gezeigt"] = True
    spieler["quest_oros_listen"] = "entscheidung_offen"
    if erstmals:
        quest_meldung(
            "update", "Ein Name auf der Liste",
            "Entscheide, wie du mit den Belegen und Rabans Angebot umgehst."
        )
    warte_auf_taste("Weiter")

def oros_listen_entscheidung_holen():
    entscheidungen = spieler.get("entscheidungen", {})
    if (
        spieler.get("quest_oros_listen") != "abgeschlossen"
        or not isinstance(entscheidungen, dict)
    ):
        return None
    entscheidung = entscheidungen.get("oros_falschaussage")
    if entscheidung in ("beweise_vorgelegt", "levin_beschuldigt"):
        return entscheidung
    return None


def oros_listen_entscheidung():
    bisher = oros_listen_entscheidung_holen()
    if bisher is not None:
        text_ausgeben(
            "Du hast Levin mit den Belegen entlastet."
            if bisher == "beweise_vorgelegt"
            else "Du hast die falsche Aussage unterschrieben. Levin und Ida haben Oros verlassen."
        )
        warte_auf_taste("Weiter")
        return

    belege = spieler.get("oros_listen_belege", {})
    if (
        spieler.get("quest_oros_listen") not in (
            "belege_vergleichen", "entscheidung_offen"
        )
        or spieler.get("oros_listen_vergleich") is not True
        or not isinstance(belege, dict)
        or not all(belege.get(key) is True for key in (
            "bestellung", "krankenstube", "frachtbrief", "verkauf"
        ))
    ):
        text_ausgeben("Prüfe zuerst alle vier Belege und vergleiche sie.")
        warte_auf_taste("Weiter")
        return

    while True:
        ort_titel("Universität von Oros - Deine Aussage")
        print("1. Ignaz die Belege vorlegen und Levin entlasten")
        print("2. Rabans falsche Aussage unterschreiben")
        print("3. Später entscheiden")
        auswahl = eingabe_menu(1, 3, sonder_tasten=())
        if auswahl == 3:
            return
        if auswahl == 2 and spieler.get("oros_listen_angebot_gezeigt") is not True:
            text_ausgeben("Höre dir zuerst Rabans Angebot an, bevor du über seine Aussage entscheidest.")
            warte_auf_taste("Weiter")
            continue

        if auswahl == 1:
            entscheidung = "beweise_vorgelegt"
            text_ausgeben("Du legst Ignaz die geprüften Belege vor und stehst persönlich für sie ein. Damit stellst du dich gegen Raban. Seine Weste und seinen Lagerzugang erhältst du nicht.")
        else:
            entscheidung = "levin_beschuldigt"
            print('Aussage: "Ich habe gesehen, wie Levin die Unterlagen zu Lieferung 17 verändert hat."')
            text_ausgeben("Du hast das nicht beobachtet. Deine Unterschrift kann Levin seine Stelle und seinen Aufenthalt kosten. Raban verspricht dir die Reiseweste mit Schutz 4 und Lagerzugang mit einmalig zwei Bandagen und einem Heiltrank.")
        print("Diese Entscheidung lässt sich anschließend nicht wechseln.")
        print()
        print("1. Ja, diese Aussage abgeben")
        print("2. Nein, zurück zur Auswahl")
        if eingabe_menu(1, 2, sonder_tasten=()) == 2:
            continue
        if not oros_listen_abschliessen(entscheidung):
            text_ausgeben("Der Abschluss konnte nicht durchgeführt werden. Es wurde keine neue Entscheidung gespeichert.")
            warte_auf_taste("Weiter")
        return



def oros_listen_abschliessen(entscheidung):
    from copy import deepcopy

    if entscheidung not in ("beweise_vorgelegt", "levin_beschuldigt"):
        return False

    belege = spieler.get("oros_listen_belege", {})
    entscheidungen = spieler.get("entscheidungen", {})
    if (
        spieler.get("quest_oros_listen") not in (
            "belege_vergleichen", "entscheidung_offen"
        )
        or spieler.get("oros_listen_vergleich") is not True
        or not isinstance(belege, dict)
        or not all(belege.get(key) is True for key in (
            "bestellung", "krankenstube", "frachtbrief", "verkauf"
        ))
        or not isinstance(entscheidungen, dict)
        or "oros_falschaussage" in entscheidungen
    ):
        return False

    verrat = entscheidung == "levin_beschuldigt"
    if verrat and (
        spieler.get("quest_oros_listen") != "entscheidung_offen"
        or spieler.get("oros_listen_angebot_gezeigt") is not True
    ):
        return False

    # Erst auf einer Kopie vorbereiten: bei Fehlern keine halbe Auszahlung.
    daten = deepcopy(spieler)
    if verrat:
        weste_id = "verstaerkte_reiseweste"
        if not system_ausruestungsgegenstand_besitzt(daten, weste_id):
            if not system_ausruestungsgegenstand_hinzufuegen(daten, weste_id):
                text_ausgeben("Die Reiseweste konnte nicht übergeben werden. Die Entscheidung bleibt offen.")
                return False
        daten["oros_listen_lagerzugang"] = True

    daten.setdefault("entscheidungen", {})["oros_falschaussage"] = entscheidung
    daten["quest_oros_listen"] = "abgeschlossen"
    spieler.update(daten)

    ort_titel("Universität von Oros - Ein Name auf der Liste")
    if verrat:
        text_ausgeben("Du unterschreibst die Aussage, obwohl du Levin nicht beim Verändern der Unterlagen gesehen hast.")
        text_ausgeben("Raban reicht sie bei der Verwaltung ein. Wenige Tage später verliert Levin seine Stelle und muss die Universität verlassen.")
        text_ausgeben("Im Archiv legt Levin seine wenigen Sachen in eine Tasche. Ida wartet an der Tür und geht mit ihm. Keiner der beiden verabschiedet sich von dir.")
        text_ausgeben("Raban übergibt dir die Verstärkte Reiseweste. Sie liegt in deinem Ausrüstungsinventar. Sein Lager steht dir nun offen.")
    else:
        text_ausgeben("Du legst Ignaz die geprüften Belege mit ihrer Herkunft vor und stehst für deine Aussage ein.")
        text_ausgeben("Ignaz protokolliert die Unterlagen und leitet sie an die zuständige Prüfstelle weiter. Ihre Prüfung bestätigt die Lieferabweichung und entlastet Levin.")
        text_ausgeben("Raban verliert die Zuständigkeit für Lieferung 17. Seine Beziehungen bleiben bestehen; als du ihm im Hof begegnest, wendet er sich wortlos ab.")
        text_ausgeben("Levin bleibt im Archiv, Ida in der Krankenstube.")
        print()
        text_ausgeben("[Levin] Danke, dass du meinen Namen nicht einfach geopfert hast.")

    quest_meldung("abgeschlossen", "Ein Name auf der Liste")
    warte_auf_taste("Weiter")
    return True

def oros_listen_lagerpaket():
    from copy import deepcopy

    if (
        oros_listen_entscheidung_holen() != "levin_beschuldigt"
        or spieler.get("oros_listen_lagerzugang") is not True
    ):
        text_ausgeben("Raban hat dir keinen Zugang zu seinem Lager gewährt.")
        warte_auf_taste("Weiter")
        return
    if spieler.get("oros_listen_lagerpaket_erhalten", False) is not False:
        text_ausgeben("Das zugesagte Vorratspaket hast du bereits abgeholt. Weitere Vorräte gibt Raban nicht kostenlos heraus.")
        warte_auf_taste("Weiter")
        return

    inventar = spieler.get("inventar_items", {})
    traenke = spieler.get("heiltränke", 0)
    bandagen = inventar.get("bandage", 0) if isinstance(inventar, dict) else None
    if any(
        not isinstance(wert, int) or isinstance(wert, bool) or wert < 0
        for wert in (traenke, bandagen)
    ):
        text_ausgeben("Das Vorratspaket konnte nicht übergeben werden. Es bleibt für dich zurückgelegt.")
        warte_auf_taste("Weiter")
        return

    daten = deepcopy(spieler)
    if not inventar_item_hinzufuegen(daten, "bandage", 2):
        text_ausgeben("Das Vorratspaket konnte nicht übergeben werden. Es bleibt für dich zurückgelegt.")
        warte_auf_taste("Weiter")
        return
    daten["heiltränke"] = traenke + 1
    daten["oros_listen_lagerpaket_erhalten"] = True
    spieler.update(daten)
    ort_titel("Universität von Oros - Rabans Lager")
    text_ausgeben("Raban lässt dich ein kleines Bündel von einem Regal nehmen. Darin liegen zwei Bandagen und ein Heiltrank.")
    print("Erhalten: 2 Bandagen, 1 Heiltrank. Das Paket ist einmalig.")
    warte_auf_taste("Weiter")



def oros_versorgungshof():
    if spieler.get("quest_oros_listen") not in (
        "lieferung_pruefen", "belege_vergleichen",
        "entscheidung_offen", "abgeschlossen"
    ):
        return

    oros_ruhe_szene("versorgungshof")

    ort_titel("Universität von Oros - Versorgungshof")
    if spieler.get("oros_listen_hof_besucht") is not True:
        text_ausgeben(
            "Zwischen einer Laderampe und niedrigen Lagertüren "
            "stehen Karren mit Säcken und verschnürten Ballen."
        )
        text_ausgeben(
            "Ein Mann vergleicht Frachtblätter mit den Zeichen auf den Kisten."
        )
        text_ausgeben("[Raban] Wenn du eine Lieferung suchst: erst Nummer, dann Ware.")
        text_ausgeben(
            "Daneben befestigt ein reisender Händler Leinenballen "
            "auf seinem Wagen. An einem hängt noch die Nummer 17."
        )
        spieler["oros_listen_hof_besucht"] = True
        warte_auf_taste("Weiter")

    while True:
        ort_titel("Universität von Oros - Versorgungshof")
        print("1. Raban nach dem Frachtbrief zu Lieferung 17 fragen")
        print("2. Den Händler nach seinen Leinenballen fragen")
        print("3. Die vier Belege vergleichen")
        print("4. Mit Raban über seine Abmachung sprechen")
        print("5. Deine Aussage abgeben oder den Abschluss ansehen")
        print("6. Das zugesagte Vorratspaket aus Rabans Lager abholen")

        zurueck_nummer = 7

        if tiefen_zukauf_offen():
            print("7. Bei Raban Lampenöl und Seil kaufen")
            zurueck_nummer = 8

        print(f"{zurueck_nummer}. Zurück zur zentralen Halle")
        print()
        print("[S] Status")
        print("[I] Inventar")
        print("[J] Questlog/Erfolge")
        print("[T] Talente")
        print("[Q] Speichern / Menü")

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=("s", "i", "j", "t", "q")
        )

        if auswahl == "s":
            status()
            return
        if auswahl == "i":
            inventar()
            return
        if auswahl == "j":
            questlog()
            return
        if auswahl == "t":
            talentmenue()
            return
        if auswahl == "q":
            spielmenue()
            return

        if auswahl == zurueck_nummer:
            return
        if auswahl == 7:
            raban_zukauf()
            continue
        if auswahl == 5:
            oros_listen_entscheidung()
            continue
        if auswahl == 6:
            oros_listen_lagerpaket()
            continue
        if auswahl == 3:
            oros_listen_belege_vergleichen()
            continue
        if auswahl == 4:
            raban_angebot_anhoeren()
            continue

        print()
        if auswahl == 1:
            text_ausgeben("Raban zieht einen Frachtbrief aus dem Stapel.")
            print("Lieferung 17: Zwölf Ballen Leinen vollständig abgeladen.")
            print("Empfang bestätigt: Raban.")
            text_ausgeben("[Raban] Hier. Der Fuhrmann hat alles abgeliefert.")
            beleg_id = "frachtbrief"
        else:
            text_ausgeben(
                "[Händler] Vier Ballen. Raban hat sie mir als Überschuss verkauft."
            )
            text_ausgeben(
                "Der Händler öffnet seine Mappe und zeigt dir den Kaufbeleg."
            )
            print("Lieferung 17: Vier Ballen Leinen von Raban gekauft.")
            print("Zahlung persönlich an Raban; Empfang von ihm quittiert.")
            text_ausgeben("[Händler] Bezahlt habe ich. Die Quittung behalte ich.")
            beleg_id = "verkauf"

        belege = spieler.get("oros_listen_belege")
        if not isinstance(belege, dict):
            belege = {}
            spieler["oros_listen_belege"] = belege
        belege[beleg_id] = True
        warte_auf_taste("Weiter")



