def schutz_quest_status():
    return spieler.get(
        "quest_schutzverwaltung",
        "nicht_entdeckt"
    )


def schutz_vorbereitung_fertig():
    return (
        spieler.get("schutz_siegelordnung_erhalten") is True
        and spieler.get("schutz_versorgung_organisiert") is True
    )


def schutz_finch_brief_offen():
    return (
        stelle_quest_status() == "abgeschlossen"
        and schutz_quest_status() == "nicht_entdeckt"
    )


def schutz_amtsstube_offen():
    return (
        schutz_quest_status() == "amtsstube"
        or (
            schutz_quest_status() == "vorbereiten"
            and schutz_vorbereitung_fertig()
        )
    )


def schutz_siegelordnung_offen():
    return (
        schutz_quest_status() == "vorbereiten"
        and spieler.get("schutz_siegelordnung_erhalten") is not True
    )


def schutz_versorgung_offen():
    return (
        schutz_quest_status() == "vorbereiten"
        and spieler.get("schutz_versorgung_organisiert") is not True
    )


def schutz_valerie_offen():
    return (
        schutz_quest_status() in ("vorbereiten", "mauer")
        and spieler.get("schutz_valerie_gesprochen") is not True
    )


def schutz_vorbereitung_meldung():
    if schutz_vorbereitung_fertig():
        ziel = "Melde dich bei Haller in der Amtsstube der Schutzverwaltung."
    elif spieler.get("schutz_siegelordnung_erhalten") is True:
        ziel = "Gib Finchs Liste im Versorgungshof ab."
    else:
        ziel = "Hol die Siegelordnung im Archiv."

    quest_meldung(
        "update",
        "Die Antwort der Schutzverwaltung",
        ziel
    )


def schutz_finch_satz():
    saetze = {
        "nicht_entdeckt": (
            "[Finch] Ich habe alle drei Fälle beigelegt. Mehr kann ich im "
            "Moment nicht tun."
        ),
        "amtsstube": (
            "[Finch] Haller erwartet uns in der Amtsstube. Ich komme ungern "
            "zu spät zu einer Behörde."
        ),
        "vorbereiten": (
            "[Finch] Siegelordnung und Versorgung. Vorher öffnet Haller nichts."
        ),
        "mauer": (
            "[Finch] Morgen früh am alten Wegweiser. "
            "Die Öffnung ist vorbereitet."
        ),
        "abgeschlossen": (
            "[Finch] Ich habe versucht, die Treppe zu vermessen, so weit das "
            "Licht reichte. Es hat nicht weit gereicht."
        )
    }

    mauer_satz = mauer_finch_satz()

    if schutz_quest_status() == "abgeschlossen" and mauer_satz:
        return mauer_satz

    return saetze.get(
        schutz_quest_status(),
        saetze["nicht_entdeckt"]
    )


