def tiefen_zukauf_offen():
    return spieler.get("schutz_ausruestung_erhalten") is True


def tiefen_zukauf_sortiment(item_ids, preise=TIEFEN_ZUKAUF_PREISE):
    return {
        item_id: {"preis": preise[item_id]}
        for item_id in item_ids
    }


def raban_zukauf():
    entscheidung = oros_listen_entscheidung_holen()
    preise = TIEFEN_ZUKAUF_PREISE

    if entscheidung == "levin_beschuldigt":
        preise = TIEFEN_ZUKAUF_PREISE_FREUNDLICH
        begruessung = (
            "[Raban] Öl und Seil. Für dich rechne ich freundlich ab."
        )

    elif entscheidung == "beweise_vorgelegt":
        begruessung = (
            "[Raban] Öl und Seil. Zum vollen Preis, wie gesagt."
        )

    else:
        begruessung = (
            "[Raban] Öl und Seil. Kostet, was es kostet."
        )

    haendler_kaufen(
        "Universität von Oros - Rabans Lager",
        begruessung,
        tiefen_zukauf_sortiment(("lampenoel", "seil"), preise)
    )


