def tiefen_treppenschacht():
    zustand = tiefen_zustand()
    titel = "TIEFEN - Treppenschacht"

    if tiefen_kopf("tiefen_treppenschacht"):
        if tiefen_licht_an():
            text_ausgeben(
                "Die Treppe windet sich eng um eine Achse aus grauem "
                "Stein. Die Stufen sind gleich hoch, jede einzelne, als "
                "hätte jemand sie mit demselben Maß geschnitten."
            )
            text_ausgeben(
                "Hinter dir wird das Licht der Halle mit jeder Windung "
                "kleiner. Dann bleibt nur noch deine Laterne."
            )
            print()
            text_ausgeben(
                "Die Luft ist kühl und trocken. Kein Tropfen, kein Moos. "
                "Nichts lebt hier, das du sehen könntest."
            )
            print()
            text_ausgeben(
                "[Ahrens] Treppenschacht. Zweiundvierzig Stufen bis zur "
                "ersten Wendung."
            )
            text_ausgeben("Er schreibt, ohne stehen zu bleiben.")
        else:
            text_ausgeben(
                "Die Treppe windet sich eng nach unten. Hinter dir wird "
                "das Licht der Halle mit jeder Windung kleiner, bis es "
                "ganz fehlt."
            )
            text_ausgeben(
                "Unter deinen Füßen sind die Stufen gleich hoch, jede "
                "einzelne. Die Luft ist kühl und trocken."
            )
            print()
            text_ausgeben(
                "[Ahrens] Zweiundvierzig Stufen bis zur ersten Wendung."
            )

        seite_wechseln(titel)

        print(tiefen_licht_zeile())
        print()

        text_ausgeben(
            "Weiter unten bricht die Treppe ab. Ein Stück der Wand ist "
            "nachgerutscht und hat ein Dutzend Stufen mit sich genommen."
        )

        if tiefen_licht_an():
            text_ausgeben(
                "Darunter, gut zwei Mannslängen tiefer, setzt sich die "
                "Treppe fort, als wäre nichts gewesen."
            )
        else:
            text_ausgeben(
                "Dein Fuß findet keine nächste Stufe. Von unten kommt ein "
                "Echo zurück, nicht sehr tief."
            )

    elif zustand.get("seil_bruch") is True:
        text_ausgeben(
            "Die Treppe windet sich um ihre Achse aus grauem Stein. An "
            "der Bruchstelle hängt das Seil ruhig am eisernen Ring.",
            art="menue"
        )

    else:
        text_ausgeben(
            "Die Treppe windet sich um ihre Achse aus grauem Stein. An "
            "der Bruchstelle fehlen ein Dutzend Stufen.",
            art="menue"
        )

    if tiefen_sicht() and zustand.get("ring_gesehen") is not True:
        print()
        text_ausgeben(
            "In der Wand über der Bruchstelle sitzt ein eiserner Ring. "
            "Alt, aber fest."
        )
        text_ausgeben(
            "[Finch] Jemand hat damit gerechnet, dass hier einmal etwas "
            "nachgibt."
        )
        zustand["ring_gesehen"] = True

    optionen = []

    if zustand.get("seil_bruch") is True:
        optionen.append((
            "Am Seil zum Messgang hinabsteigen",
            lambda: tiefen_gehen(
                "tiefen_messgang",
                "Du lässt dich am Seil hinab. Finch folgt dir, Ahrens "
                "als Letzter."
            )
        ))
    else:
        if (
            tiefen_sicht()
            and zustand.get("ring_gesehen") is True
            and item_besitzt("seil")
        ):
            optionen.append((
                "Das Seil am Ring befestigen",
                tiefen_bruch_seil
            ))

        optionen.append((
            "Über die Trümmer klettern [Geschick]",
            tiefen_bruch_klettern
        ))

    optionen.append(tiefen_laterne_option())
    optionen.append((
        "Zurück nach Oros hinaufsteigen",
        tiefen_schacht_hinauf
    ))

    tiefen_menue(optionen)


