def tiefen_messgang():
    zustand = tiefen_zustand()

    if tiefen_kopf("tiefen_messgang"):
        if tiefen_licht_an():
            text_ausgeben(
                "Unten öffnet sich ein Gang, so gerade, dass das Licht der "
                "Laterne an seinem Ende nicht mehr ankommt."
            )
        else:
            text_ausgeben(
                "Unten wird der Boden eben. Ein Gang führt geradeaus, so "
                "gerade, dass du nach wenigen Schritten die Wand nicht "
                "mehr brauchst."
            )

        zustand["messgang_entdeckt"] = True

    elif tiefen_begegnung_aktuell() is None:
        text_ausgeben(
            "Der Messgang liegt gerade und still vor dir.",
            art="menue"
        )

    gegner_typ = tiefen_begegnung_aktuell()

    if gegner_typ is not None:
        tiefen_begegnung(gegner_typ)
        return

    if tiefen_sicht() and zustand.get("vertiefungen_gesehen") is not True:
        print()
        text_ausgeben(
            "An der Wand sitzen in regelmäßigen Abständen flache "
            "Vertiefungen."
        )
        zustand["vertiefungen_gesehen"] = True

    if tiefen_licht_an() and zustand.get("kerben_gesehen") is not True:
        print()
        text_ausgeben(
            "In den Boden sind Markierungen eingelassen. Schmale Kerben in "
            "gleichem Abstand, jede gleich tief."
        )
        text_ausgeben(
            "Finch kniet sich hin und misst den Abstand zwischen zwei "
            "Kerben mit den Fingern. Dann zwischen den nächsten beiden."
        )
        text_ausgeben("[Finch] Gleich. Und die nächsten auch.")
        text_ausgeben(
            "[Finch] Es ist beinahe, als wäre der Gang selbst Teil einer "
            "Messung."
        )
        print()
        text_ausgeben(
            "Über jeder Vertiefung in der Wand sitzt ein kleines Zeichen. "
            "Wartungsstellen, wenn man Finch glaubt."
        )
        zustand["kerben_gesehen"] = True

    if tiefen_sicht() and zustand.get("seitenschacht_gesehen") is not True:
        print()
        text_ausgeben(
            "Auf halber Länge führt ein schmaler Schacht senkrecht nach "
            "unten. Am Grund zeichnet sich eine Nische mit einem Absatz "
            "aus Stein ab."
        )
        text_ausgeben(
            "Daneben sitzt ein zweiter eiserner Ring im Fels. Ein "
            "niedriger Durchgang führt in Windungen ebenfalls hinunter."
        )
        zustand["seitenschacht_gesehen"] = True

    nach_meldung = mauer_quest_status() == "abstieg"

    if nach_meldung:
        tiefen_quest_ziel(
            "kammer_finden",
            "Folge dem Messgang bis zu seinem Ende."
        )

    optionen = []

    if "tiefen_kammer" in zustand.get("besucht", []):
        optionen.append((
            "Zur Kammer der Reihe gehen",
            tiefen_zur_kammer
        ))
    else:
        optionen.append((
            "Dem Messgang bis zu seinem Ende folgen",
            tiefen_zur_kammer
        ))

    # Ohne Licht und Nachtauge lässt sich der Seitenschacht ertasten.
    if (
        zustand.get("seitenschacht_gesehen") is not True
        and not tiefen_sicht()
    ):
        optionen.append((
            "Die Wände des Messgangs abtasten",
            tiefen_messgang_abtasten
        ))

    if zustand.get("seitenschacht_gesehen") is True:
        if zustand.get("seil_seite") is True:
            optionen.append((
                "Am Seil zur Wartungsnische hinabsteigen",
                lambda: tiefen_gehen(
                    "tiefen_wartungsnische",
                    "Du lässt dich am Seil in den Schacht hinab."
                )
            ))
        else:
            if tiefen_sicht() and item_besitzt("seil"):
                optionen.append((
                    "Ein Seil am zweiten Ring befestigen",
                    tiefen_seitenschacht_seil
                ))

            optionen.append((
                "Den Umweg über die Nebenkammer nehmen",
                lambda: tiefen_gehen(
                    "tiefen_nebenkammer",
                    "Du bückst dich in den niedrigen Durchgang."
                )
            ))

    if (
        tiefen_sicht()
        and zustand.get("vertiefungen_gesehen") is True
        and tiefen_hammer_dabei()
    ):
        optionen.append((
            "Mit dem Hammer gegen eine Vertiefung klopfen",
            tiefen_hammer_klopfen
        ))

    if stollen_offen():
        optionen.append((
            "In den verschütteten Seitenstollen kriechen",
            stollen_betreten
        ))

    if abtrennung_status() == "messgang":
        optionen.append((
            "Zu Finch an die Vertiefungen gehen [!]",
            abtrennung_messgang
        ))

    optionen.append(tiefen_laterne_option())
    optionen.append((
        "Zurück zum Treppenschacht",
        tiefen_treppe_hinauf
    ))

    tiefen_menue(optionen, nach_meldung)


