def wegstation_messmappe_anzeigen():
    daten = wegstation_messung_daten()
    messungen = [
        nummer for nummer in ("1", "2")
        if daten.get(f"messung{nummer}") is True
    ]

    if not messungen:
        return

    print()
    design_text(
        "Peilwerte (Teilstriche):",
        design="wissen",
        art="menue"
    )
    print()

    kopf = f"{'':<28}{'Register':>9}"
    for nummer in messungen:
        kopf += f"{nummer + '. Messung':>12}"
    print(kopf)

    for punkt_id, punkt_name in WEGSTATION_PEILPUNKTE:
        zeile = f"{punkt_name:<28}{WEGSTATION_PEILWERTE['register'][punkt_id]:>9}"
        for nummer in messungen:
            zeile += f"{WEGSTATION_PEILWERTE[nummer][punkt_id]:>12}"
        print(zeile)

    print()
    print("Erste Messung: Abweichung bei Letzthafen.")

    if "2" in messungen:
        print(
            "Zweite Messung: Abweichung bei Letzthafen bestätigt, neue "
            "Abweichung bei Eichenruh. Beide Blätter von Ahrens unterschrieben."
        )

    offene_tore_messmappe_anzeigen()


def wegstation_amtsstube():
    # Gibt True zurück, wenn die Amtsstube einen Wegstation-Inhalt gezeigt hat.
    status = wegstation_quest_status()

    if wegstation_quest_verfuegbar():
        text_ausgeben(
            "Haller sitzt am Fenstertisch über einem Stapel Blätter. Ahrens "
            "steht neben ihm."
        )
        menue_trenner()
        print()
        print("1. Mit Haller über die Außenverbindungen sprechen [!]")
        print("2. Später wiederkommen")

        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            wegstation_haller_auftrag()

        return True

    if status == "messung1":
        text_ausgeben(
            "Haller sieht auf, als du eintrittst. Finch ist schon da."
        )
        menue_trenner()
        print()
        print("1. Haller die Messmappe geben [!]")
        print("2. Später wiederkommen")

        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            wegstation_haller_bericht1()

        return True

    if status in ("auftrag", "bericht1"):
        text_ausgeben("Haller sieht kurz von seinem Blatt auf.")
        text_ausgeben(
            "[Haller] Die Wegstation. Professor Finch und Ahrens sind über die "
            "Messungen unterrichtet."
        )
        return True

    if status == "messung2":
        text_ausgeben("Haller sieht kurz von seinem Blatt auf.")
        text_ausgeben(
            "[Haller] Ich will die Auswertung von Dr. Vance dabei haben. "
            "Bringen Sie mir beides zusammen."
        )
        return True

    if status == "auswertung":
        text_ausgeben(
            "Haller sieht auf, als du eintrittst. Finch ist schon da."
        )
        menue_trenner()
        print()
        print("1. Haller die Messmappe und Valeries Auswertung geben [!]")
        print("2. Später wiederkommen")

        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            wegstation_haller_zoegern()
            wegstation_ahrens_warten()

        return True

    if status == "pruefung":
        text_ausgeben(
            "Haller liest in den Siegelakten. Ahrens' Platz am Seitentisch "
            "ist leer."
        )
        wegstation_ahrens_warten()
        return True

    if status == "abgeschlossen" and abtrennung_status() == "nicht_begonnen":
        text_ausgeben(
            "Haller und Ahrens gehen gemeinsam eine Liste durch. Sie sehen "
            "nur kurz auf."
        )
        menue_trenner()
        print()
        print("1. Mit Haller über die angeordnete Maßnahme sprechen [!]")
        print("2. Später wiederkommen")

        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            abtrennung_beginn()

        return True

    if status == "abgeschlossen" and abtrennung_status() == "auftrag":
        text_ausgeben("Haller sieht kurz von seinem Blatt auf.")
        text_ausgeben(
            "[Haller] Morgen früh, am TIEFEN-Zugang. Die Schutzverwaltung "
            "stellt Licht."
        )
        return True

    if status == "abgeschlossen":
        text_ausgeben("Hallers Platz am Fenster ist leer.")
        return True

    return False


def wegstation_ahrens_warten():
    menue_trenner()
    print()
    print("1. Warten, bis Ahrens zurück ist [!]")
    print("2. Später wiederkommen")

    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        wegstation_entscheidung()


