    text_ausgeben("[Finch] Es geht nicht zurück.")

    daten["ruecknahme"] = True

    print()
    text_ausgeben(
        "Haller nimmt Ahrens die Schutzordnung aus der Hand und liest die "
        "Seite selbst. Dann noch einmal."
    )
    text_ausgeben("[Haller] Hier steht, wie man zurückstellt.")
    text_ausgeben("Er blättert um. Die nächste Seite ist leer.")
    text_ausgeben("[Haller] Nicht, was man tut, wenn es nicht zurückgeht.")

    seite_wechseln(titel)

    text_ausgeben(
        "Aus dem Messgang kommt ein Laut, ein tiefes Knirschen, aus einer "
        "Richtung, in der niemand steht."
    )
    text_ausgeben(
        "Einer der Arbeiter dreht sich um und lässt seine Laterne fallen. Sie "
        "erlischt nicht."
    )
    text_ausgeben("[Finch] Der Messgang. Jetzt.")

    zustand = tiefen_zustand()
    besucht = zustand.setdefault("besucht", [])

    if "tiefen_messgang" not in besucht:
        besucht.append("tiefen_messgang")

    spieler["ort"] = "tiefen_messgang"

    abtrennung_ziel_setzen("messgang")
    warte_auf_taste("Weiter")


