def abtrennung_messgang():
    titel = "TIEFEN - Messgang"
    daten = abtrennung_daten()
    ort_titel(titel)

    text_ausgeben(
        "Finch kniet vor der Wand, das Messbuch K-IV aufgeschlagen auf dem "
        "Knie. Die Peilscheibe liegt neben ihm auf dem Boden."
    )
    text_ausgeben("Das Knirschen ist leiser geworden. Ganz aufgehört hat es nicht.")
    text_ausgeben(
        "[Finch] Die Reihe verliert ihre Ausrichtung. Nicht alle Vertiefungen. "
        "Eine Gruppe."
    )
    text_ausgeben(
        "[Finch] Wenn ich eine davon festhalten kann, hält vielleicht der "
        "Rest. Vielleicht."
    )
    text_ausgeben("[Finch] Ich brauche Ihre Hände. Meine zittern.")
    print()
    text_ausgeben(
        "[Finch] Im Messbuch steht: vierte Vertiefung nach dem Seitenschacht. "
        "Zwischen Schacht und Vertiefung sieben Kerben im Boden."
    )
    text_ausgeben(
        "[Finch] Und darunter eine Skizze: Die Kerbe der Führung steht in "
        "einer Linie mit den Kerben im Boden."
    )

    if tiefen_zustand().get("hammer_klang") is True:
        print()
        text_ausgeben(
            "Du erinnerst dich an den Klang, der durch den Stein lief. Er kam "
            "nicht von dort, wo es jetzt knirscht."
        )
    elif untersuchung_pruefung("wahrnehmung", 2):
        print()
        text_ausgeben(
            "Vor der vierten Vertiefung nach dem Seitenschacht sind die Kerben "
            "noch scharf."
        )

    menue_trenner()
    print()
    print("1. Die Vertiefung, vor der die Kerben gerade verwischen")
    print("2. Die vierte Vertiefung nach dem Seitenschacht")
    print("3. Die Vertiefung, aus deren Richtung das Knirschen kam")

    if eingabe_menu(1, 3, sonder_tasten=()) != 2:
        abtrennung_fehlgriff(
            "Du legst die Hand in die Vertiefung. Finch zählt die Kerben, "
            "schüttelt den Kopf."
        )
        text_ausgeben("[Finch] Nicht diese. Vierte nach dem Schacht.")

    print()
    text_ausgeben("Du zählst die Kerben davor. Sieben.")
    text_ausgeben("[Finch] Die. Ganz sicher die.")

    seite_wechseln(titel)

    text_ausgeben(
        "In der Vertiefung sitzt eine lose Steinführung, kaum größer als eine "
        "Hand. Auch sie trägt eine Kerbe."
    )
    text_ausgeben(
        "[Finch] Sie muss so stehen, wie es im Buch steht. Ich sage Ihnen, ob "
        "die Peilung stimmt."
    )

    menue_trenner()
    print()
    print("1. Die Kerbe auf die Kerben im Boden ausrichten")
    print("2. Die Kerbe in Richtung IV-C drehen")
    print("3. Die Führung quer zum Gang stellen")

    if eingabe_menu(1, 3, sonder_tasten=()) != 1:
        abtrennung_fehlgriff("Finch richtet die Peilscheibe aus, liest ab.")
        text_ausgeben("[Finch] Nein. Weiter weg vom Wert als vorher. Zurück.")

    print()
    text_ausgeben(
        "Du drehst die Führung, bis ihre Kerbe in einer Linie mit den Kerben "
        "im Boden liegt."
    )
    text_ausgeben("Finch visiert. Einmal. Zweimal.")
    text_ausgeben(
        "[Finch] Das ist der Wert aus dem Buch. Festhalten. Nicht loslassen."
    )

    mittel = []

    if item_besitzt("seil"):
        mittel.append(("seil", "Mit einem Seil festbinden (wird verbraucht)"))
    if item_besitzt("bandage"):
        mittel.append(("bandage", "Mit einer Bandage festbinden (wird verbraucht)"))
    if item_besitzt("holz"):
        mittel.append(("holz", "Mit einem Stück Holz verkeilen (wird verbraucht)"))

    mittel.append(("guertel", "Finchs Gürtel nehmen"))

    menue_trenner()
    print()

    for nummer, (_, text) in enumerate(mittel, start=1):
        print(f"{nummer}. {text}")

    wahl = mittel[eingabe_menu(1, len(mittel), sonder_tasten=()) - 1][0]

    if wahl != "guertel" and not item_entfernen(wahl, 1):
        wahl = "guertel"

    seite_wechseln(titel)

    text_ausgeben({
        "seil": "Du schlingst das Seil zweimal um die Führung und zurrst es an "
                "einem Vorsprung fest.",
        "bandage": "Du wickelst die Bandage straff um Führung und Kante, bis "
                   "nichts mehr nachgibt.",
        "holz": "Du treibst das Holz zwischen Führung und Wand. Es knackt, aber "
                "es sitzt.",
        "guertel": "Finch zieht seinen Gürtel aus den Schlaufen und reicht ihn "
                   "dir, ohne den Blick von der Scheibe zu nehmen."
    }[wahl])
    text_ausgeben("Du lässt los. Die Führung bewegt sich nicht.")
    text_ausgeben(
        "Finch visiert noch einmal. Das Knirschen ist verstummt. Hier "
        "jedenfalls."
    )
    text_ausgeben("[Finch] Es hält.")
    text_ausgeben("Er blickt auf die nächste Markierung.")
    text_ausgeben("[Finch] Nicht überall. Aber hier hält es.")
    text_ausgeben(
        "Hinter euch ruft Ahrens die Arbeiter zur Treppe. Der Treppenschacht "
        "steht still. Einer nach dem anderen steigt hinauf."
    )

    if daten.get("fehlgriffe", 0) > 0:
        text_ausgeben(
            "Als Letzter kommt ein Arbeiter, der zu lange im Gang gewartet hat. "
            "Er humpelt. Ein Stein hat ihn am Knöchel getroffen."
        )

    text_ausgeben("[Finch] Solange das hält, kommen sie raus. Gehen wir.")

    daten["fixiert_mit"] = wahl
    daten["halten"] = True
    spieler["quest_letzte_abtrennung"] = "wahl"

    abtrennung_wahl()


def abtrennung_wahl():
    titel = "Universität von Oros - Zentrale Halle"
