RISS_KOENIGSRING_ENDE = 5  # Schritt der Waldlichtung


def oros_listen_verfallen():
    return (
        (spieler.get("entscheidungen") or {}).get("oros_falschaussage")
        == "verfallen"
    )


def riss_liste_anwenden():
    # Einmalig nach dem Riss. Nichts wird zurückgesetzt, Abschlüsse bleiben.
    daten = kapitel6_daten()

    if daten.get("riss_liste") is True:
        return

    daten["riss_liste"] = True
    stand = spieler.get("quest_oros_listen")

    if stand in ("lieferung_pruefen", "belege_vergleichen", "entscheidung_offen"):
        # Levins Fall bleibt offen; kein Abschluss, keine Belohnung.
        daten["levin_stand_beim_riss"] = stand
        spieler.setdefault("entscheidungen", {})["oros_falschaussage"] = "verfallen"


def riss_koenigsring_ende(reise_daten):
    # Nach dem Riss endet der Königsring hinter der alten Wegstation.
    if (
        not akt1_riss_geschehen()
        or reise_daten.get("weg_id") != "koenigsring"
        or reise_daten.get("ziel") != "Letzthafen"
        or reise_daten.get("aktueller_schritt", 0) < RISS_KOENIGSRING_ENDE
    ):
        return False

    ort_titel(reise_daten.get("name", "Königsring"))
    text_ausgeben(
        "Im Register der Wegstation ist Letzthafen noch immer verzeichnet. "
        "Doch vor dir ist keine Fortsetzung des Königsrings zu erkennen."
    )
    text_ausgeben(
        "Dort, wo der Königsring weiterführen müsste, verliert sich die "
        "Straße im Gras."
    )
    text_ausgeben("Du erinnerst dich an diesen Weg. Vor dir liegt keiner mehr.")
    warte_auf_taste("Zurück")
    return True


def riss_nach_eichenruh():
    reise(
        "Eichenruh",
        "Du erreichst wieder den nördlichen Ortsrand Eichenruhs.",
        "Hinter dir verschwindet der Höhenweg zwischen den Bäumen.",
        gebiet_modus=True
    )


def eichenruh_heimkehr():
    # Erste Rückkehr nach Eichenruh nach dem Riss, einmal.
    if not akt1_riss_geschehen():
        return

    riss_liste_anwenden()
    daten = kapitel6_daten()

    if daten.get("eichenruh_heimkehr") is True:
        return

    daten["eichenruh_heimkehr"] = True
    ort_titel("Eichenruh")
    ort_nachricht_anzeigen()

    text_ausgeben(
        "Die letzten Pfähle stehen am Waldrand, dort, wo du mit Finch "
        "umgekehrt bist. Dahinter beginnt der Weg ins Dorf, wie er immer "
        "begonnen hat."
    )
    text_ausgeben(
        "Eichenruh ist da. Rauch steigt aus den Kaminen. Am Brunnen streiten "
        "zwei Frauen über einen Eimer."
    )
    text_ausgeben(
        "Niemand sieht dich an, als kämst du von weit her. Für sie bist du "
        "nur ein paar Tage fort gewesen."
    )

    seite_wechseln("Eichenruh")

    text_ausgeben("Am Wegweiser in der Dorfmitte bleibst du stehen.")
    text_ausgeben(
        "Ein Arm zeigt nach Oros. Einer zum Marktplatz. Einer zur Köhlerei."
    )
    text_ausgeben("Der vierte Arm ist leer.")
    text_ausgeben(
        "Dort, wo ein Name stehen müsste, ist das Holz glatt. Keine "
        "ausgekratzten Buchstaben, keine Reste alter Farbe."
    )
    text_ausgeben(
        "Du erinnerst dich an den Königsring. An die Wegstation. An die "
        "Straße nach Letzthafen."
    )
    text_ausgeben("Aber auf dem Wegweiser steht nichts davon.")

    warte_auf_taste("Weiter")


