def eichenruh_nach_riss_satz(npc):
    # Einmal je Figur nach dem Riss.
    if not akt1_riss_geschehen() or npc_reaktion_gezeigt(npc, "nach_riss"):
        return

    npc_reaktion_markieren(npc, "nach_riss")
    zeilen = list(EICHENRUH_NACH_RISS_SAETZE.get(npc, []))

    if npc == "hilda":
        lohn = (spieler.get("entscheidungen") or {}).get("hilda_lohn")
        zeilen = [
            HILDA_NACH_RISS_SAETZE.get(lohn, HILDA_NACH_RISS_SAETZE["normal"])
        ]

    if npc == "tomas" and spieler.get("quest_ein_name_fehlt") == "abgeschlossen":
        zeilen.append(
            "[Tomas] Der Fuhrmann aus Letzthafen? Seit der Nacht hat ihn keiner "
            "gesehen. Hier kommt ja auch keiner mehr von dort."
        )

    for zeile in zeilen:
        text_ausgeben(zeile)

    print()


def spieler_max_lebenspunkte():
    # Bisher überall fest 100 (Zuhause, Tränke, Anzeige); Level 7 passt das
    # zentral an.
    return 100


def riss_notlager_ausruhen():
    ort_titel("Universität von Oros - Zentrale Halle")
    text_ausgeben(
        "Zwischen den Säulen ist ein Schlafplatz frei geworden. Eine gefaltete "
        "Decke liegt auf einer der Matten."
    )

    if spieler["lebenspunkte"] < spieler_max_lebenspunkte():
        text_ausgeben("Du legst dich hin und ruhst dich eine Weile aus.")
        spieler["lebenspunkte"] = spieler_max_lebenspunkte()
        print()
        print("Deine Lebenspunkte wurden vollständig wiederhergestellt.")
    else:
        text_ausgeben("Du fühlst dich bereits vollständig erholt.")

    warte_auf_taste()


