def caelen_status():
    return spieler.get("quest_caelen", "nicht_entdeckt")


def caelen_ziel():
    return {
        "untersuchen": "Untersuche die Hütte am nördlichen Waldrand.",
        "bjorn": "Frag Bjorn nach dem Zeichen auf dem Wanderstab.",
        "pfad": "Kehre zur Hütte am nördlichen Waldrand zurück."
    }.get(caelen_status(), "")


def caelen_ziel_setzen(status, neu=False):
    spieler["quest_caelen"] = status

    quest_meldung(
        "neu" if neu else "update",
        "Die Hütte am Waldrand",
        caelen_ziel()
    )

    warte_auf_taste("Weiter")


def eichenruh_huette_offen():
    # Erst nach der Heimkehr nach dem Riss.
    return (
        akt1_riss_geschehen()
        and kapitel6_daten().get("eichenruh_heimkehr") is True
    )


def caelen_huette():
    titel = "Eichenruh - Hütte am Waldrand"

    if caelen_status() == "nicht_entdeckt":
        ort_titel(titel)
        text_ausgeben(
            "Abseits des Fadens der Erinnerung steht eine kleine, verwitterte "
            "Hütte zwischen den Bäumen."
        )
        text_ausgeben(
            "Der Boden vor der Tür ist festgetreten. Jemand muss hier lange ein "
            "und aus gegangen sein."
        )
        text_ausgeben("Wem die Hütte gehört, weißt du nicht.")
        caelen_ziel_setzen("untersuchen", neu=True)

    while True:
        ort_titel(titel)
        text_ausgeben(
            "Die kleine, verwitterte Hütte steht abseits des Fadens der "
            "Erinnerung zwischen den Bäumen."
        )

        optionen = [
            ("kraeuter", "Die Kräuter ansehen"),
            ("kerben", "Die Kerben ertasten"),
            ("stab", "Den Wanderstab ansehen")
        ]

        if caelen_status() == "pfad":
            optionen.append(("pfad", "Hinter die Hütte gehen [!]"))

        optionen.append(("zurueck", "Zurück nach Eichenruh"))

        menue_trenner()
        print()

        for nummer, (_, text) in enumerate(optionen, start=1):
            print(f"{nummer}. {text}")

        aktion = optionen[eingabe_menu(1, len(optionen), sonder_tasten=()) - 1][0]
        print()

        if aktion == "zurueck":
            return

        if aktion == "pfad":
            caelen_abschluss()
            return

        if aktion == "kraeuter":
            text_ausgeben(
                "Auf einem Brett liegen Kräuter, sorgfältig nach Art sortiert. "
                "Jedes Bündel ist mit einer anderen Folge von Knoten verschnürt. "
                "Die Blätter sind trocken, aber nicht alt."
            )

        elif aktion == "kerben":
            text_ausgeben(
                "Am Türpfosten und an den Regalen sind Kerben, in Holz "
                "geschnitten, in Gruppen. Man kann sie nicht lesen. Man kann "
                "sie ertasten."
            )

            if untersuchung_pruefung("wissen", 2):
                text_ausgeben(
                    "Die Kerben befinden sich an Stellen, die eine tastende "
                    "Hand leicht erreichen kann. Sie markieren offenbar "
                    "Abstände und Orientierungspunkte, keine Schriftzeichen."
                )

        else:
            text_ausgeben(
                "An der Wand lehnt ein Wanderstab. Der Griff ist neu "
                "umwickelt. In das Leder ist ein kleines Zeichen gebrannt: ein "
                "Hammer über einer Linie."
            )

            if caelen_status() == "untersuchen":
                caelen_ziel_setzen("bjorn")
                continue

        warte_auf_taste("Weiter")


def caelen_bjorn():
    text_ausgeben(
        "Du beschreibst Bjorn das Zeichen auf dem Griff: ein Hammer über einer "
        "Linie."
    )
    text_ausgeben("[Bjorn] Das ist mein Zeichen. Den Griff hab ich gemacht.")
    text_ausgeben("Er holt ein dickes Buch unter der Werkbank hervor und blättert.")
    text_ausgeben(
        "[Bjorn] Hier. „Caelen – Wanderstab, Griff erneuert – Hütte am "
        "Waldrand.“"
    )
    text_ausgeben("Er liest es noch einmal.")
    text_ausgeben("[Bjorn] Das ist meine Schrift. Ich hab den Namen geschrieben.")
    text_ausgeben("[Bjorn] Ich weiß nur nicht, wem ich den Stab gegeben habe.")

    caelen_ziel_setzen("pfad")


def caelen_abschluss():
    ort_titel("Eichenruh - Hütte am Waldrand")
    text_ausgeben(
        "Caelen. Der Name passt zu nichts, woran du dich erinnerst. Und doch "
        "hat jemand diese Kräuter sortiert, diesen Stab benutzt, diese Kerben "
        "geschnitten."
    )
    text_ausgeben(
        "Hinter der Hütte führt ein schmaler Pfad in den Wald. Nach ein paar "
        "Schritten endet er an einer Stelle, an der der Boden aussieht wie "
        "überall."
    )
    text_ausgeben(
        "Keine Markierung verrät, ob der Pfad schon immer hier endete."
    )

    spieler["quest_caelen"] = "abgeschlossen"
    quest_meldung("abgeschlossen", "Die Hütte am Waldrand")
    warte_auf_taste("Weiter")


