def wegstation_messung_zusatz(nummer):
    # Optionale Wahrnehmungsprobe und Hammer, je Messung einmal.
    daten = wegstation_messung_daten()
    titel = "Alte Wegstation - Vorhof"

    while True:
        optionen = []

        if nummer == 1 and daten.get("probe1") is not True:
            optionen.append(("probe", "Die Kerbe am zweiten Pfosten genauer ansehen [Wahrnehmung]"))

        if (
            tiefen_hammer_dabei()
            and daten.get(f"hammer{nummer}") is not True
            and (nummer == 1 or daten.get("hammer1") is True)
        ):
            optionen.append(("hammer", "Den Pfosten mit dem Hammer anklopfen"))

        if not optionen:
            return

        optionen.append(("weiter", "Die Messung abschließen"))

        menue_trenner()
        print()

        for index, (_, text) in enumerate(optionen, start=1):
            print(f"{index}. {text}")

        art = optionen[eingabe_menu(1, len(optionen), sonder_tasten=()) - 1][0]

        if art == "weiter":
            return

        ort_titel(titel)

        if art == "probe":
            daten["probe1"] = True

            if untersuchung_pruefung("wahrnehmung", 2):
                text_ausgeben(
                    "Du siehst dir die Kerbe auf dem zweiten Pfosten genau an. "
                    "Sie ist so verwittert wie die anderen. Niemand hat daran "
                    "gearbeitet."
                )
            else:
                text_ausgeben(
                    "Du siehst dir die Kerbe auf dem zweiten Pfosten an. Mehr "
                    "als Moos und alte Verwitterung erkennst du nicht."
                )

        elif nummer == 1:
            daten["hammer1"] = True
            text_ausgeben(
                "Du legst den Hammer neben die Kerbe. Der Kopf passt nicht "
                "hinein, aber der Stein klingt beim leichten Anklopfen genauso "
                "wie die anderen."
            )
            text_ausgeben("[Finch] Zumindest klingt er nicht anders als die übrigen.")

        else:
            daten["hammer2"] = True
            text_ausgeben(
                "Du klopfst den ersten Pfosten wieder an. Derselbe Klang wie "
                "beim letzten Mal."
            )
            text_ausgeben("[Finch] Der Stein ist derselbe. Natürlich ist er das.")

        print()


