def gegner_schaden_berechnen(starker_angriff):
    if starker_angriff:
        return random.randint(30, 45)

    return random.randint(6, 12)

def gegner_greift_an(name_gegner, lebenspunkte_spieler, schaden_gegner, flucht = False):
    if flucht:
        print(f"{name_gegner} erwischt dich bei der Flucht!")
    else:
        print(f"{name_gegner} greift dich an!")
    lebenspunkte_spieler -= schaden_gegner
    print(f"→ {schaden_gegner} Schaden")

    return lebenspunkte_spieler

def truhe(gold, heiltränke, diamanten):
    
    truhen_wurf = random.randint(1, 100)
    if truhen_wurf <= 60:
        print()
        print("Du hast eine kleine Truhe gefunden.")
        beute = random.randint(1, 4)
        if beute <= 3:
            gefundenes_gold_klein = random.randint(1, 20)
            print(f"Du findest einen Heiltrank und {gefundenes_gold_klein} Gold!")
            heiltränke = heiltränke + 1
            gold = gold + gefundenes_gold_klein
        elif beute == 4:
            print("Die Truhe ist leer.")
    elif 61 <= truhen_wurf <= 90:
        print()
        print("Du hast eine mittlere Truhe gefunden.")
        beute = random.randint(1, 4)
        if beute <= 3:
            gefundenes_gold_mittel = random.randint(20, 50)
            print(f"Du findest einen Heiltrank und {gefundenes_gold_mittel} Gold!")
            heiltränke = heiltränke + 1
            gold = gold + gefundenes_gold_mittel
        elif beute == 4:
            print("Du findest nichts von Wert.")
    elif 91 <= truhen_wurf <= 100:
        print()
        print("Du hast eine große Truhe gefunden.")
        beute = random.randint(1, 100)
        if beute <= 60:
            gefundenes_gold_gross = random.randint(50, 100)
            print(f"Du findest einen Heiltrank und {gefundenes_gold_gross} Gold!")
            heiltränke = heiltränke + 1
            gold = gold + gefundenes_gold_gross
        elif 61 <= beute <= 85:
            gefundenes_gold_gross = random.randint(50, 100)
            print(f"Du findest ein Diamant und {gefundenes_gold_gross} Gold!")
            diamanten = diamanten + 1
            gold = gold + gefundenes_gold_gross
        else:
            print("Zu deiner Überraschung ist die Truhe leer.")


    return gold, heiltränke, diamanten

def lichtung_steine_lesen(waechter_lebt):
    ort_titel(
        "Waldlichtung - Die Steine am Rand"
    )

    if waechter_lebt:
        text_ausgeben(
            "Du bleibst, wo du bist. Der Waldwächter steht zwischen dir und den "
            "Steinen am anderen Ende der Lichtung. Er rührt sich nicht."
        )

        text_ausgeben(
            "Aber nicht alle Steine stehen dort drüben. Drei liegen am Rand, "
            "ganz in deiner Nähe, halb unter Moos."
        )

        print()

        text_ausgeben(
            "Langsam, ohne den Blick lange von ihm zu nehmen, ziehst du mit "
            "einem Stock Linien in die Erde. Von diesem Stein zu jenem, von "
            "dort zum nächsten."
        )

        text_ausgeben(
            "Drei Steine sind wenig. Aber die Linien zwischen ihnen laufen nicht "
            "kreuz und quer. Zwei zeigen über den Rand der Lichtung hinaus in "
            "dieselbe Richtung. Nach Süden, quer durch den Wald."
        )

        print()

        text_ausgeben(
            "Du überträgst die Richtung in deine Notizen. Der Waldwächter steht "
            "noch immer an derselben Stelle."
        )

        if spieler_pruefung("sensibilitaet", 2):
            print()

            text_ausgeben(
                "Selbst von hier spürst du, dass die Steine zusammengehören."
            )

    else:
        text_ausgeben(
            "Du gehst langsam am Rand der Lichtung entlang und zählst die Steine. "
            "Es sind mehr, als du beim ersten Mal gesehen hast. Einige liegen "
            "halb unter Moos."
        )

        text_ausgeben(
            "Du versuchst es so, wie das Messbuch es zeigt: nicht jeden Stein für "
            "sich, sondern die Linien zwischen ihnen."
        )

        print()

        text_ausgeben(
            "Mit einem Stock ziehst du die Linien in die feuchte Erde. Von diesem "
            "Stein zu jenem, von dort zum nächsten."
        )

        text_ausgeben(
            "Keiner der Steine steht in der Mitte von irgendetwas. Doch die Linien "
            "zwischen ihnen laufen nicht kreuz und quer. Mehrere zeigen über den "
            "Rand der Lichtung hinaus in dieselbe Richtung. Nach Süden, quer "
            "durch den Wald."
        )

        print()

        text_ausgeben(
            "Du überträgst die Richtung, so gut es geht, in deine Notizen."
        )

        if spieler_pruefung("sensibilitaet", 2):
            print()

            text_ausgeben(
                "Als du die Hand auf den nächsten Stein legst, ist das Gefühl von "
                "damals sofort wieder da, nur ruhiger. Die Steine gehören "
                "zusammen. Und sie gehören zu etwas, das weiter reicht als diese "
                "Lichtung."
            )

    print()

    if weg_status("pfad_des_vergessens") == "entdeckt":
        text_ausgeben(
            "Nach Süden, über die Felder hinter Eichenruh hinaus. Dorthin, wo "
            "der Pfad des Vergessens durch den Wald führt."
        )

        spieler[
            "quest_wege_verbinden"
        ] = "pfad_folgen"

        quest_meldung(
            "update",
            "Was die Wege verbindet",
            "Folge der Richtung von der Lichtung zum Pfad des Vergessens."
        )

    else:
        text_ausgeben(
            "Nach Süden, über die Felder hinter Eichenruh hinaus. Du kennst dort "
            "keinen Weg. Aber in Eichenruh gibt es jemanden, der die alten Wege "
            "kennt."
        )

        spieler[
            "quest_wege_verbinden"
        ] = "tomas_fragen"

        quest_meldung(
            "update",
            "Was die Wege verbindet",
            "Frag Tomas, ob in dieser Richtung ein alter Weg verläuft."
        )

    warte_auf_taste(
        "Weiter"
    )


def waldlichtung_nach_sieg():
    ort_titel(
        "Waldlichtung"
    )

    ort_nachricht_anzeigen()

    text_ausgeben(
        "Die Lichtung liegt still.",
        art="menue"
    )

    menue_trenner()
    print()

    optionen = []

    if spieler.get("quest_wege_verbinden") == "lichtung_untersuchen":
        optionen.append(
            ("steine", "Die Steine am Rand untersuchen [!]")
        )

    optionen.append(("status", "Status anzeigen"))
    optionen.append(("inventar", "Inventar öffnen"))
    optionen.append(("zurueck", "Zum Königsring zurück"))

    for nummer, (_, text) in enumerate(optionen, 1):
        print(f"{nummer}. {text}")

    auswahl = eingabe_menu(
        1,
        len(optionen),
        sonder_tasten=()
    )

    aktion = optionen[auswahl - 1][0]

    if aktion == "steine":
        lichtung_steine_lesen(
            waechter_lebt=False
        )

    elif aktion == "status":
        status()

    elif aktion == "inventar":
        inventar()

    elif aktion == "zurueck":
        aktive_reise = spieler.get(
            "reise"
        )

        if isinstance(
            aktive_reise,
            dict
        ):
            spieler["ort"] = aktive_reise.get(
                "gebiet",
                "Wald"
            )

            ort_nachricht_setzen(
                "Du verlässt die stille Lichtung und kehrst zum Königsring zurück."
            )

        else:
            spieler["ort"] = "Eichenruh"

            ort_nachricht_setzen(
                "Du verlässt die stille Lichtung.",
                "Nach einiger Zeit erreichst du wieder Eichenruh."
            )


def bosskampf(lebenspunkte, spiel_laeuft, gold, diamanten, heiltränke, ort):
    if spieler["waldwaechter_besiegt"]:
        aktive_reise = spieler.get(
            "reise"
        )

        if isinstance(
            aktive_reise,
            dict
        ):
            ort = aktive_reise.get(
                "gebiet",
                "Wald"
            )

        else:
            ort = "Eichenruh"

        return lebenspunkte, spiel_laeuft, gold, diamanten, heiltränke, ort

    ort_titel(
        "Waldwächter"
    )

    text_ausgeben(
        "Der Wächter senkt den Schwerpunkt. Unter seinem Gewicht knacken "
        "Wurzeln und trockenes Holz."
    )

    text_ausgeben(
        "Noch immer stößt er keinen Laut aus."
    )

    print()

    kampf_ergebnis = kampf_starten(
        lebenspunkte=lebenspunkte,
        heiltraenke=heiltränke,
        waffe=spieler["waffe"],
        gegner_typ="Waldwächter",
        kampf_situation={
            "gebiet": "Wald",
            "umgebung": "Lichtung",
            "tageszeit": spieler.get(
                "tageszeit",
                "Tag"
            ),
            "wetter": spieler.get(
                "wetter",
                "Klar"
            )
        }
    )

    lebenspunkte = kampf_ergebnis["lebenspunkte"]
    heiltränke = kampf_ergebnis["heiltraenke"]

    if kampf_ergebnis["gewonnen"]:
        gefundenes_gold = random.randint(
            70,
            100
        )

        print()

        text_ausgeben(
            "Der letzte Treffer zwingt den Waldwächter zurück. Ein Knie "
            "schlägt schwer auf dem Waldboden auf."
        )

        text_ausgeben(
            "Eine seiner Hände greift nicht nach dir, sondern nach einem der "
            "verwitterten Steine am Rand der Lichtung."
        )

        print()

        text_ausgeben(
            "Die breiten Finger ruhen einen Moment auf dem alten Stein. "
            "Dann verliert die Gestalt jede Spannung."
        )

        text_ausgeben(
            "Moos, Rinde und dunkle Erde sinken langsam in sich zusammen."
        )

        print()

        design_text(
            "WALDWÄCHTER BESIEGT",
            design="positiv",
            art="ereignis"
        )

        spieler[
            "waldwaechter_besiegt"
        ] = True

        spieler[
            "besiegte_gegner"
        ] += 1

        diamanten += 5
        gold += gefundenes_gold

        print()

        text_ausgeben(
            "Durch den Kampf hat sich Erde am Fuß eines der Randsteine gelöst. "
            "Darunter kommt eine flache, mit Steinen ausgelegte Mulde zum Vorschein."
        )

        text_ausgeben(
            "Zwischen verrotteten Stoffresten liegen alte Münzen und fünf klare, "
            "harte Steine."
        )

        print()

        design_text(
            f"Gefunden: {gefundenes_gold} Gold und 5 Diamanten",
            design="positiv",
            art="menue"
        )

        akt1_lernerfahrung(
            "waldwaechter_koerper"
        )

        seite_wechseln(
            "Waldlichtung"
        )

        text_ausgeben(
            "Als der Wind wieder durch die Kronen geht, verändert sich etwas."
        )

        text_ausgeben(
            "Nicht in der Lichtung. In deiner Wahrnehmung."
        )

        print()

        text_ausgeben(
            "Die verwitterten Steine am Rand wirken plötzlich nicht mehr zufällig "
            "verteilt. Noch bevor du ihre Linie bewusst verfolgst, spürst du, "
            "dass sie zusammengehören."
        )

        text_ausgeben(
            "Jenseits der Bäume weißt du für einen kurzen Augenblick genau, "
            "wo der Königsring verläuft, obwohl du ihn nicht sehen kannst."
        )

        print()

        akt1_lernerfahrung(
            "waldwaechter_erwachen"
        )

        print()

        text_ausgeben(
            "Das Gefühl wird schwächer, verschwindet aber nicht vollständig."
        )

        text_ausgeben(
            "Dir fehlt noch ein Wort für das, was du gerade wahrgenommen hast."
        )

        spieler[
            "waldwaechter_schwelle_erlebt"
        ] = True

        warte_auf_taste(
            "Zum Königsring zurück"
        )

        aktive_reise = spieler.get(
            "reise"
        )

        if isinstance(
            aktive_reise,
            dict
        ):
            ort = aktive_reise.get(
                "gebiet",
                "Wald"
            )

            ort_nachricht_setzen(
                "Du findest zwischen den Bäumen zurück zum Königsring.",
                "Der erste Vogelruf über der alten Straße klingt plötzlich "
                "ungewöhnlich laut.",
                "Die Lichtung ist längst nicht mehr zu sehen. Trotzdem weißt du "
                "noch immer, in welcher Richtung sie liegt."
            )

        else:
            ort = "Eichenruh"

            ort_nachricht_setzen(
                "Du lässt die stille Lichtung hinter dir.",
                "Das seltsame neue Gefühl begleitet dich bis nach Eichenruh."
            )

    elif kampf_ergebnis["besiegt"]:
        print()

        design_text(
            "Game Over",
            design="gefahr",
            art="menue"
        )

        spiel_laeuft = False

    return (
        lebenspunkte,
        spiel_laeuft,
        gold,
        diamanten,
        heiltränke,
        ort
    )



def gluecksprobe(prozent=20):
    return random.randint(
        1,
        100
    ) <= prozent


def wald_bach_geheimweg_pruefen(*, gezielt=False):
    if wald_fund_bekannt(
        "bach_geheimweg_entdeckt"
    ):
        return False

    if gezielt is not True and not gluecksprobe(
        20
    ):
        return False

    wald_fund_setzen(
        "bach_geheimweg_entdeckt"
    )

    print()

    text_ausgeben(
        "Für einen kurzen Moment spiegelt sich Licht "
        "an einer Stelle, die dir zuvor nicht aufgefallen ist."
    )

    print()

    design_text(
        "Zwischen den Wurzeln zeichnet sich "
        "ein schmaler Weg ab.",
        design="wissen",
        art="menue"
    )

    return True

