def revierherr_pruefen(gebiet, gegner_typ):
    zaehler = spieler.setdefault("revier_jagden", {})
    zaehler[gebiet] = zaehler.get(gebiet, 0) + 1

    daten = REVIERHERREN.get(gebiet)
    buch = spieler.get("jagdbuch", {})
    if (
        daten is None
        or buch.get(daten["herr"], {}).get("beute") is True
        or zaehler[gebiet] <= 2
        or hybrid_probe_offen(spieler)
        or random.randint(1, 100) > 8
    ):
        return gegner_typ

    print()
    for zeile in daten["texte"]:
        text_ausgeben(zeile)
    print()
    design_text(
        daten["titel"],
        design="warnung",
        art="ereignis"
    )
    print()
    print("1. Dich ihm stellen")
    print("2. Langsam zurückweichen")

    auswahl = eingabe_menu(1, 2, sonder_tasten=())

    if auswahl == 2:
        text_ausgeben(
            daten["zurueck"],
            art="menue"
        )
        warte_auf_taste(daten["taste"])
        return None

    return daten["herr"]


def wildspur_jagd_vorbereiten():
    spur_untersucht = False

    def zeit_verstreichen():
        ressourcen_vorkommen_regenerieren("wald_holz")
        return status_schritte_abschliessen()

    while spieler.get("spiel_laeuft", True):
        ort_titel("Wald - Wildspur")

        lebenspunkte = spieler["lebenspunkte"]
        print(f"Lebenspunkte: {lebenspunkte}/100")

        if lebenspunkte <= 35:
            design_text(
                "Du bist schwer verletzt. Eine Jagd ist jetzt besonders "
                "gefährlich. Öffne das Inventar, um dich zu versorgen, "
                "oder brich die Jagd ab und raste.",
                design="warnung",
                art="menue"
            )

        print()

        faehrten_schwelle = (
            3 - talent_bonus(spieler, "wildspur_schwelle")
        )

        faehrten_erkannt = (
            spur_untersucht
            or spieler_pruefung(
                "wahrnehmung",
                faehrten_schwelle
            )
        )

        if faehrten_erkannt:
            print("Du kannst die Fährten unterscheiden.")
            print()
            print("1. Den Pfotenabdrücken folgen - Wolf [1 Schritt]")
            print("2. Den tiefen Hufspuren folgen - Keiler [1 Schritt]")
        else:
            print("Du kannst die frischen Fährten noch nicht unterscheiden.")
            print()
            print("1. Der unbekannten Fährte folgen [1 Schritt]")
            print("2. Spuren genauer untersuchen [1 zusätzlicher Schritt]")

        print("3. Inventar öffnen")
        print("4. Jagd abbrechen")
        print()
        print("[Schritt]: Blutung, Gift und Mahlzeit-Wirkungen laufen dabei einen Schritt weiter.")

        auswahl = eingabe_menu(1, 4, sonder_tasten=())

        if auswahl == 4:
            return None

        if auswahl == 3:
            inventar()
            continue

        if not faehrten_erkannt and auswahl == 2:
            if not zeit_verstreichen():
                return None

            spur_untersucht = True
            text_ausgeben(
                "Du untersuchst die Spuren genauer. Zwischen den "
                "Pfotenabdrücken erkennst du auch tiefe Hufspuren. "
                "Jetzt kannst du die Fährte eines Wolfs oder Keilers wählen."
            )
            warte_auf_taste("Fährte wählen")
            continue

        if not spieler.get("waffe"):
            design_text(
                "Rüste im Inventar eine Waffe aus, bevor du jagst.",
                design="warnung",
                art="menue"
            )
            warte_auf_taste()
            continue

        if not zeit_verstreichen():
            return None

        if faehrten_erkannt:
            return "Wolf" if auswahl == 1 else "Keiler"

        return random.choice(("Wolf", "Keiler"))

    return None

def wald_knoten_aktion_ausfuehren(
    knoten_id,
    aktion_id
):

    # -------------------------
    # BACHSUCHE UND VERBORGENER SEITENARM
    # -------------------------

    if aktion_id == "bach_geheimweg_suchen":
        if (
            knoten_id != "bachufer"
            or not spieler.get("spiel_laeuft", True)
            or wald_fund_bekannt("bach_geheimweg_entdeckt")
        ):
            return

        ort_titel("Wald - Bachlauf")
        print("Du suchst das Ufer Schritt für Schritt ab.")
        print("Blutung und Gift wirken während der Suche weiter.")
        ressourcen_vorkommen_regenerieren("wald_holz")
        if not status_schritte_abschliessen():
            return

        wald_bach_geheimweg_pruefen(gezielt=True)
        warte_auf_taste("Weiter")

    elif aktion_id == "bacharm_untersuchen":
        ort_titel(
            "Wald - Verborgener Seitenarm"
        )

        text_ausgeben(
            "Du folgst dem stillen Wasser ein Stück "
            "zwischen den Wurzeln entlang."
        )

        print()

        text_ausgeben(
            "Zwischen zwei dunklen Steinen fällt dir "
            "ein matter Metallrand auf."
        )

        print()

